$$" :tutorial/id #uuid "ce4fb1c3-94ee-51c3-b10d-ce6ea0c7ff38" :tutorial/math-academy-id 6431 :tutorial/title "Introduction"} {:db/id 17592186045463 :db/ident :activity.type/lesson} {:course/id #uuid "992cac0c-bf6a-5373-95c9-02edfcfb591e" :course/math-academy-id 105 :db/id 17592186046644} {:db/id 17592186049309 :topic/id #uuid "eb56b359-bf3c-5bc4-a26b-629e05c1d464" :topic/knowledge-points [{:db/id 17592186068717 :knowledge-point/canonical-example {:db/id 17592186068491 :question/id #uuid "60c2e025-0b7e-5ac2-afec-adeb5f65eed1" :question/math-academy-id "e-14222"} :knowledge-point/id #uuid "e107f878-5b22-54bf-90fc-b8ea8a22c77d" :knowledge-point/key-prerequisites [{:db/id 17592186048267} {:db/id 17592186050734}] :knowledge-point/questions [{:db/id 17592186069130 :question/id #uuid "6dccebba-e685-5ccf-8a2e-1661e84941a8" :question/math-academy-id "q-215464"} {:db/id 17592186069131 :question/id #uuid "b467536f-aa10-576c-a9c6-ed66bbafee39" :question/math-academy-id "q-215466"} {:db/id 17592186069289 :question/id #uuid "b089f476-27d3-575d-9dec-95701d683ed8" :question/math-academy-id "q-3673"}] :knowledge-point/title "Absolute Value Inequalities Containing a Less Than (or Equal To) Symbol"} {:db/id 17592186068718 :knowledge-point/canonical-example {:db/id 17592186068510 :question/id #uuid "12d8aea9-62dd-5181-bd6e-54c11eba4152" :question/math-academy-id "e-14708"} :knowledge-point/id #uuid "65964b91-8f0e-5ffc-97d3-e5b87a6bade5" :knowledge-point/questions [{:db/id 17592186069132 :question/id #uuid "fcb879da-1b24-57e1-8cf8-e1e6de6fe967" :question/math-academy-id "q-215482"} {:db/id 17592186069133 :question/id #uuid "0ceea8c0-f989-54a6-9f70-92e530683a94" :question/math-academy-id "q-215489"} {:db/id 17592186069294 :question/id #uuid "848ad56e-2e24-5fe8-bf66-9dcd62c41f20" :question/math-academy-id "q-3693"}] :knowledge-point/title "Cases Where the Coefficient in the Absolute Value Is Negative"} {:db/id 17592186068719 :knowledge-point/canonical-example {:db/id 17592186068493 :quest