![](images/4d/4d4765d2f5e49794336d2bf35705da9fa7885ce0a619dcd3a117d28cfe66645e.png)" :tutorial/id #uuid "17eba692-165e-58c9-96a3-8aed2c660530" :tutorial/math-academy-id 6723 :tutorial/title "Introduction"} :step/id #uuid "5f6b707c-1a02-5a01-96da-00e64ed94944" :step/math-academy-id 40678 :step/next {:db/id 17592186193596}} {:db/id 17592186193596 :step/content {:db/id 17592186192742 :knowledge-point/canonical-example {:db/id 17592186192460 :question/id #uuid "273e5c07-6f92-5019-8268-bc3af728c530" :question/math-academy-id "e-10737"} :knowledge-point/id #uuid "d4b0977a-6bcb-5d7f-bec8-b10bff6d7e23" :knowledge-point/key-prerequisites [{:db/id 17592186048213} {:db/id 17592186049587}] :knowledge-point/questions [{:db/id 17592186193186} {:db/id 17592186193351}] :knowledge-point/title "Finding Alternate Interior Angles"} :step/id #uuid "8bd1113e-49e3-508c-a22f-dfa0fdd69bae" :step/math-academy-id 40680 :step/next {:db/id 17592186193673}} {:db/id 17592186193616 :step/content {:db/id 17592186192756 :knowledge-point/canonical-example {:db/id 17592186192475 :question/id #uuid "9faa078f-3129-5683-8cc4-d9b783505224" :question/math-academy-id "e-10856"} :knowledge-point/id #uuid "7e1b5c9b-4be3-5d63-a757-fb0ec6091e3c" :knowledge-point/questions [{:db/id 17592186193185} {:db/id 17592186193385}] :knowledge-point/title "Further Solving Problems With Alternate Angles"} :step/id #uuid "7f037845-d12e-5297-90be-1612950af662" :step/math-academy-id 41154} {:db/id 17592186193673 :step/content {:db/id 17592186192791 :knowledge-point/canonical-example {:db/id 17592186192515 :question/id #uuid "39e4f5cd-d815-5318-8e85-6941293da1ca" :question/math-academy-id "e-11056"} :knowledge-point/id #uuid "18bf826f-de64-5905-9e7b-b87a3b4e1227" :knowledge-point/questions [{:db/id 17592186192946} {:db/id 17592186193187}] :knowledge-point/title "Finding Alternate Exterior Angles"} :step/id #uuid "0ed50c81-73e4-55ef-8062-730a3a7ba23a" :step/math-academy-id 42013 :step/next {:db/id 17592186193674}} {:db/id 175921