 17592186237566}] :question/difficulty {:db/id 17592186045487 :db/ident :question.difficulty/moderate} :question/problem "Find ${f}^{″}(1,2)$ for the function $f(x,y)$ given that
${f}^{′}(x,y)=\begin{bmatrix}y-2xy & x-{x}^{2}\end{bmatrix}$" :question/worked-solution "For a function $f:{R}^{n}\to R,$ given by

$$
f:{{\begin{bmatrix}{x}_{1} \\ {x}_{2} \\ ⋮ \\ {x}_{n}\end{bmatrix}}_{⏟}}_{x}⟶f({x}_{1},{x}_{2},…,{x}_{n}),
$$

the second derivative of $f$ is given by the $n\times n$ matrix

$$
{f}^{″}(x)=\begin{bmatrix}\frac{{∂}^{2}f}{∂{x}_{1}^{2}} & \frac{{∂}^{2}f}{∂{x}_{1}∂{x}_{2}} & ⋯ & \frac{{∂}^{2}f}{∂{x}_{1}∂{x}_{n}} \\ \frac{{∂}^{2}f}{∂{x}_{2}∂{x}_{1}} & \frac{{∂}^{2}f}{∂{x}_{2}^{2}} & ⋯ & \frac{{∂}^{2}f}{∂{x}_{2}∂{x}_{n}} \\ ⋮ & ⋮ & ⋮ & ⋮ \\ \frac{{∂}^{2}f}{∂{x}_{n}∂{x}_{1}} & \frac{{∂}^{2}f}{∂{x}_{n}∂{x}_{2}} & ⋯ & \frac{{∂}^{2}f}{∂{x}_{n}^{2}}\end{bmatrix}.
$$

In our case, we have

$$
{f}^{″}(x,y)=\begin{bmatrix}\frac{{∂}^{2}f}{∂{x}^{2}} & \frac{{∂}^{2}f}{∂x∂y} \\ \frac{{∂}^{2}f}{∂y∂x} & \frac{{∂}^{2}f}{∂{y}^{2}}\end{bmatrix}.
$$

First, notice that since ${f}^{′}(x,y)=\begin{bmatrix}y-2xy & x-{x}^{2}\end{bmatrix},$ 
 we must have

$$
\frac{∂f}{∂x}=y-2xy,\,\frac{∂f}{∂y}=x-{x}^{2}.
$$

Now, we compute the second partial derivatives:

$$
\begin{aligned}\frac{{∂}^{2}f}{∂{x}^{2}} & =\frac{∂}{∂x}(y-2xy)=-2y\, & \frac{{∂}^{2}f}{∂x∂y} & =\frac{∂}{∂x}(x-{x}^{2})=1-2x \\ \frac{{∂}^{2}f}{∂y∂x} & =\frac{∂}{∂y}(y-2xy)=1-2x\, & \frac{{∂}^{2}f}{∂{y}^{2}} & =\frac{∂}{∂y}(x-{x}^{2})=0\end{aligned}
$$

So, the second derivative is

$$
\begin{aligned}{f}^{″}(x,y) & =\begin{bmatrix}-2y & 1-2x \\ 1-2x & 0\end{bmatrix}.\end{aligned}
$$

Finally, we evaluate this matrix at $(1,2).$ This gives

$$
{f}^{″}(1,2)=\begin{bmatrix}-4 & -1 \\ -1 & 0\end{bmatrix}.
$$"} {:db/id 17592186157791 :question/id #uuid "67d83888-c95f-5ab0-a4ad-e179570526ce" :question/math-academy-id "q-80940" :knowledge-point/_questions [{:db/id 17592186157423 :knowledge-point/id #uuid "74c4234a-3aa1-5b6b-b68b-48e6aa2b0dfb" :knowledge-point/title "Finding the Second Derivative of a Function Given Its First Derivative"}] :question/answer-fields [{:answer-field/choices [{:answer/id #uuid "ce37079c-2eca-52cb-9217-b5bdc1cb43b6" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "\begin{bmatrix}3x^{2} - y & -x \\ -x & 0\end{bmatrix}" :db/id 17592186155668} {:answer/id #uuid "d8df90ee-e70b-544e-ad57-b2bdf4264fda" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "\begin{bmatrix}3x^{2} & 0 \\ 0 & -x\end{bmatrix}" :db/id 17592186155669} {:answer/id #uuid "10fc1fef-463d-5b7a-bbce-4dff18dc6262" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "\begin{bmatrix}6x & -1 \\ -1 & 0\end{bmatrix}" :db/id 17592186155670} {:answer/id #uuid "3e3bd1d3-1790-5ddf-8382-84e4bdacfcc3" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "\begin{bmatrix}3x^{2} - y & -1 \\ -1 & -x\end{bmatrix}" :db/id 17592186155671} {:answer/id #uuid "44242b8b-5a8c-532a-847c-6076d5352455" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "\begin{bmatrix}6x & -x \\ -x & 0\end{bmatrix}" :db/id 17592186155672}] :answer-field/id #uuid "12293606-e74e-5b3d-b6fa-1d12e5769093" :answer-field/key "selection" :answer-field/type {:db/id 17592186045493 :db/ident :answer-field.type/radio} :db/id 17592186155667}] :question/problem "Find $f^{″}(x, y)$ for the function $f(x, y)$ given that
