fb048a" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "-4" :db/id 17592186343215} {:answer/id #uuid "85645fd8-88a6-5000-b519-8bb725cb257c" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "\frac{1}{4}" :db/id 17592186343380} {:answer/id #uuid "8785fc80-bda9-5f80-a872-d827ec5de9e3" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "2" :db/id 17592186343411} {:answer/id #uuid "bc91e678-6e8a-5bd2-8014-4d6dc79dba2f" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "-\frac{1}{2}" :db/id 17592186343897}] :answer-field/correct {:answer/id #uuid "85645fd8-88a6-5000-b519-8bb725cb257c" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "\frac{1}{4}" :db/id 17592186343380} :answer-field/id #uuid "aaa2dacc-4ebe-5f8c-9015-7703ef1d6e40" :answer-field/key "selection" :answer-field/type {:db/id 17592186045493 :db/ident :answer-field.type/radio} :db/id 17592186344790} {:answer/id #uuid "5bb7d97b-8ad8-525a-a7ed-77ea58145c8f" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "\frac{3}{2}" :db/id 17592186343005} {:answer/id #uuid "716f0289-aeaa-5e67-84c1-81f3b2fb048a" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "-4" :db/id 17592186343215} {:answer/id #uuid "85645fd8-88a6-5000-b519-8bb725cb257c" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "\frac{1}{4}" :db/id 17592186343380} {:answer/id #uuid "8785fc80-bda9-5f80-a872-d827ec5de9e3" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "2" :db/id 17592186343411} {:answer/id #uuid "bc91e678-6e8a-5bd2-8014-4d6dc79dba2f" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "-\frac{1}{2}" :db/id 17592186343897} {:activity/expected-seconds 1140.0 :activity/first-step {:db/id 17592186065125} :activity/id #uuid "00e08faa-77cf-50f3-bce1-d22a42a5f138" :activity/scope {:db/id 17592186048441 :topic/id #uuid "9faf7c3f-8d4f-5e48-97ed-6c10e2c5383a" :topic/math-academy-id 291} :activity/steps [{:db/id 17592186065125 :step/content {:db/id 17592186065447 :tutorial/content "Consider the following function: 

$$
f(x)= 4x^2+x, \qquad x \gt 0
$$

The domain restriction $x > 0$ means that $f$ is invertible on its entire domain. 

The point $P$ with coordinates $(2,18)$ lies on the curve $y = f(x).$ This means that the point $P'$ with coordinates $(18,2)$ lies on the curve of the inverse function $y=f^{-1}(x),$ as shown below.

![](images/3e/3e16e532743be547c766e5a6a47bae8933a8dedb2b6d0fa0d60d47cc0b37ba04.png)

How do we find $\dfrac{\textrm d y}{\textrm d x}$ at the point $P'?$

For this, we will use the fact that the slope of the tangent to the curve $y=f^{-1}(x)$ at $P'$ is the *reciprocal* of the slope of the tangent to the curve $y=f(x)$ at $P.$

$$
\begin{aligned}{\frac{\text{d}y}{\text{d}x}|}_{{P}^{′}}=\frac{1}{({\frac{\text{d}y}{\text{d}x}|}_{P})}\end{aligned}
$$

Calculating $\dfrac{\textrm d y}{\textrm d x}$ at $P$ is straightforward. First, we differentiate $y=f(x).$ This gives

$$
\dfrac{\textrm{d}y}{\textrm{d}x}  = 8x + 1,
$$

and then plugging in $x=2$ gives

$$
\left.\dfrac{\textrm{d}y}{\textrm{d}x}\right|_P = 8(2)+1 = 17.
$$

Finally, we take the reciprocal:

$$
\left.\dfrac{\textrm{d}y}{\textrm{d}x}\right|_{P'}= \dfrac{1}{17}
$$

We can summarize this process using the following formula:

$$
\left(f^{-1}\right)'(x) = \dfrac{1}{f'(f^{-1}(x))}
$$

To help remember this formula, note that it's okay to swap the derivative symbol (the prime) with the inverse symbol (the exponent of $-1$) as long as we take the reciprocal afterward." :tutorial/id #uuid "a1f70bcd-9b56-5fdd-ba18-58b625c05af0" :tutorial/math-academy-id 9132 :tutorial/title "Introduction"} :step/id #uuid "1da740a0-e78c-558d-b559-528c35ca81d7" :step/math-academy-id 187680 :step/next {:db/id 17592186065126}} {:db/id 17592186065126 :step/content {:db/id 17592186064251 :knowledge-point/canonical-example {:db/id 17592186063999 :question/id #uuid "d113528f-a3ff-5f28-b071-bcf355a36b45" :question/math-academy-id "e-14720"} :knowledge-point/id #uuid "4270c31c-80f1-5b5d-bca8-e16a47206c2b" :knowledge-point/key-prerequisites [{:db/id 17592186048686} {:db/id 17592186049352}] :knowledge-point/questions [{:db/id 17592186064519} {:db/id 17592186064520} {:db/id 17592186233936} {:db/id 17592186247085} {:db/id 17592186247086} {:db/id 17592186247096} {:db/id 17592186275370} {:db/id 17592186275375} {:db/id 17592186275377} {:db/id 17592186287889} {:db/id 17592186297349} {:db/id 17592186317276} {:db/id 17592186317277} {:db/id 17592186317278} {:db/id 17592186317279} {:db/id 17592186479082} {:db/id 17592186479119} {:db/id 17592186479132} {:db/id 17592186487398}] :knowledge-point/title "Calculating the Derivative of an Inverse Function From a Graph"} :step/id #uuid "16c7f862-0b61-56ca-b731-b881c09a79a7" :step/math-academy-id 187681 :step/next {:db/id 17592186065127}} {:db/id 17592186065127 :step/content {:db/id 17592186064252 :knowledge-point/canonical-example {:db/id 17592186063998 :question/id #uuid "121d5f8c-3b38-5c75-aec1-646dc7d2f2f8" :question/math-academy-id "e-14719"} :knowledge-point/id #uuid "37e05385-7cb6-5f21-b0d8-a7641d912d5b" :knowledge-point/key-prerequisites [{:db/id 17592186048191}] :knowledge-point/questions [{:db/id 17592186064618} {:db/id 17592186064883} {:db/id 17592186233516} {:db/id 17592186233648} {:db/id 17592186234120} {:db/id 17592186275185} {:db/id 17592186275348} {:db/id 17592186275349} {:db/id 17592186275350} {:db/id 17592186275351} {:db/id 17592186275352} {:db/id 17592186292542} {:db/id 17592186297350} {:db/id 17592186297351} {:db/id 17592186297352} {:db/id 17592186317280} {:db/id 17592186317281} {:db/id 17592186317282} {:db/id 17592186317283} {:db/id 17592186317284} {:db/id 17592186317285} {:db/id 17592186317286} {:db/id 17592186365453} {:db/id 17592186409836} {:db/id 17592186479102} {:db/id 17592186505744}] :knowledge-point/title "Calculating the Derivative of an Inverse Function"} :step/id #uuid "006b4fae-82f7-53a6-a492-7df130468acf" :step/math-academy-id 187684 :step/next {:db/id 17592186065128}} {:db/id 17592186065128 :step/content {:db/id 17592186065448 :tutorial/content "The following table gives the values of functions $f(x)$ and $f'(x)$ at some points. 

| **$x$** | $f(x)$ | $f'(x)$ |
| --- | --- | --- |
| $1$ | $2$ | $3$ |
| $2$ | $1$ | $12$ |

Let's use this data to find $(f^{-1})'(1).$ 

Recall that the formula for the derivative of the inverse is

$$
(f^{-1})'(x) = \dfrac{1}{f'(f^{-1}(x))}.
$$

Substituting $x=1,$ we have

$$
(f^{-1})'(1) = \dfrac{1}{f'(f^{-1}(1))}.
$$

From the table, we see that $f(2)=1$, hence $f^{-1}(1)=2$, and also $f'(2)=12$. Therefore

$$
\begin{aligned}({f}^{-1})^{′}(1) & =\frac{1}{{f}^{′}({f}^{-1}(1))} \\  & =\frac{1}{{f}^{′}(2)} \\  & =\frac{1}{12}.\end{aligned}
$$

We can also use the rule for calculating derivatives of inverse functions in conjunction with other rules of differentiation. Let's see an example." :tutorial/id #uuid "3e542fea-8d0a-5c0c-ba69-3ec1685ecf92" :tutorial/math-academy-id 9136 :tutorial/title "Calculating Derivatives Using Tables"} :step/id #uuid "2950a7d5-38ee-59bf-b277-9aeb378c6c62" :step/math-academy-id 187687 :step/next {:db/id 17592186065129}} {:db/id 17592186065129 :step/content {:db/id 17592186064253 :knowledge-point/canonical-example {:db/id 17592186064000 :question/id #uuid "9e531872-846f-5e75-97c0-dd2db3515558" :question/math-academy-id "e-14721"} :knowledge-point/id #uuid "b492068c-2bd2-5611-baab-780959d24c3d" :knowledge-point/key-prerequisites [{:db/id 17592186048813} {:db/id 17592186050961}] :knowledge-point/questions [{:db/id 17592186064525} {:db/id 17592186064542} {:db/id 17592186233131} {:db/id 17592186234375} {:db/id 17592186234376} {:db/id 17592186234377} {:db/id 17592186247101} {:db/id 17592186247102} {:db/id 17592186247103} {:db/id 17592186247108} {:db/id 17592186247109} {:db/id 17592186297353} {:db/id 17592186297354} {:db/id 17592186317287} {:db/id 17592186317288} {:db/id 17592186317289} {:db/id 17592186317290} {:db/id 17592186317291} {:db/id 17592186317292} {:db/id 17592186317293} {:db/id 17592186332754} {:db/id 17592186345130} {:db/id 17592186345131} {:db/id 17592186345132} {:db/id 17592186365890} {:db/id 17592186409835} {:db/id 17592186479075} {:db/id 17592186479089} {:db/id 17592186505765}] :knowledge-point/title "Calculating the Derivative of an Inverse Function Using a Table"} :step/id #uuid "5c3fc6b3-0d2e-50bb-98ce-b5e82b6f6a33" :step/math-academy-id 187688 :step/next {:db/id 17592186065130}} {:db/id 17592186065130 :step/content {:db/id 17592186064254 :knowledge-point/canonical-example {:db/id 17592186064001 :question/id #uuid "d38ac709-38e8-51a1-8e08-14913c77639c" :question/math-academy-id "e-14722"} :knowledge-point/id #uuid "0b2a80aa-7882-50eb-bfe0-c0eeab72161d" :knowledge-p