$$
\begin{aligned}A & ={\lambda }_{1}{u}_{1}{u}_{1}^{T}+{\lambda }_{2}{u}_{2}{u}_{2}^{T} \\  & =9\cdot \frac{1}{\sqrt{17}}\begin{bmatrix}-4 \\ 1\end{bmatrix}\cdot \frac{1}{\sqrt{17}}\begin{bmatrix}-4 & 1\end{bmatrix}+(-8)\cdot \frac{1}{\sqrt{17}}\begin{bmatrix}1 \\ 4\end{bmatrix}\cdot \frac{1}{\sqrt{17}}\begin{bmatrix}1 & 4\end{bmatrix} \\  & =9\cdot \frac{1}{17}\begin{bmatrix}-4 \\ 1\end{bmatrix}\begin{bmatrix}-4 & 1\end{bmatrix}+(-8)\cdot \frac{1}{17}\begin{bmatrix}1 \\ 4\end{bmatrix}\begin{bmatrix}1 & 4\end{bmatrix} \\  & =\frac{1}{17}(9\cdot \begin{bmatrix}-4 \\ 1\end{bmatrix}\begin{bmatrix}-4 & 1\end{bmatrix}+(-8)\cdot \begin{bmatrix}1 \\ 4\end{bmatrix}\begin{bmatrix}1 & 4\end{bmatrix}) \\  & =\frac{1}{17}(9\cdot \begin{bmatrix}16 & -4 \\ -4 & 1\end{bmatrix}+(-8)\cdot \begin{bmatrix}1 & 4 \\ 4 & 16\end{bmatrix}) \\  & =\frac{1}{17}\begin{bmatrix}136 & -68 \\ -68 & -119\end{bmatrix} \\  & =\begin{bmatrix}8 & -4 \\ -4 & -7\end{bmatrix}.\end{aligned}
