$$

Therefore, we have

$$
\begin{aligned}A & ={\lambda }_{1}{u}_{1}{u}_{1}^{T}+{\lambda }_{2}{u}_{2}{u}_{2}^{T} \\  & =4\cdot \frac{1}{\sqrt{13}}\begin{bmatrix}2 \\ 3\end{bmatrix}\cdot \frac{1}{\sqrt{13}}\begin{bmatrix}2 & 3\end{bmatrix}+(-9)\cdot \frac{1}{\sqrt{13}}\begin{bmatrix}-3 \\ 2\end{bmatrix}\cdot \frac{1}{\sqrt{13}}\begin{bmatrix}-3 & 2\end{bmatrix} \\  & =4\cdot \frac{1}{13}\begin{bmatrix}2 \\ 3\end{bmatrix}\begin{bmatrix}2 & 3\end{bmatrix}+(-9)\cdot \frac{1}{13}\begin{bmatrix}-3 \\ 2\end{bmatrix}\begin{bmatrix}-3 & 2\end{bmatrix} \\  & =\frac{1}{13}(4\cdot \begin{bmatrix}2 \\ 3\end{bmatrix}\begin{bmatrix}2 & 3\end{bmatrix}+(-9)\cdot \begin{bmatrix}-3 \\ 2\end{bmatrix}\begin{bmatrix}-3 & 2\end{bmatrix}) \\  & =\frac{1}{13}(4\cdot \begin{bmatrix}4 & 6 \\ 6 & 9\end{bmatrix}+(-9)\cdot \begin{bmatrix}9 & -6 \\ -6 & 4\end{bmatrix}) \\  & =\frac{1}{13}\begin{bmatrix}-65 & 78 \\ 78 & 0\end{bmatrix} \\  & =\begin{bmatrix}-5 & 6 \\ 6 & 0\end{bmatrix}.\end{aligned}
$$"} {:db/id 17592186407553 :question/id #uuid "b502656e-ef35-5f6c-921c-ae3a8ea1f2a2" :question/math-academy-id "q-95721" :knowledge-point/_questions [{:db/id 17592186162015 :knowledge-point/id #uuid "785b09aa-1b82-5021-8b10-271a063cb916" :knowledge-point/title "Finding the Spectral Decomposition of a Symmetric Matrix"}] :question/answer-fields [{:answer-field/choices [{:answer/id #uuid "1f090535-e10a-5c59-9a51-2d2aae1cbc9b" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "\begin{bmatrix}-5 & 2 \\ 2 & -2\end{bmatrix}" :db/id 17592186407523} {:answer/id #uuid "3f43beb7-1a8e-5d63-bf78-07894e8c2c04" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "\begin{bmatrix}5 & 1 \\ 1 & 2\end{bmatrix}" :db/id 17592186407527} {:answer/id #uuid "5613d7c8-bedb-54d2-be91-7e80b596eb5c" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "\begin{bmatrix}-5 & 2 \\ 2 & 2\end{bmatrix}" :db/id 17592186407528} {:answer/id #uuid "694df5b3-0ed3-5486-8f0d-63bf6d2b9e75" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "\begin{bmatrix}-5 & 4 \\ 4 & -3\end{bmatrix}" :db/id 17592186407530} {:answer/id #uuid "bc550768-52c7-5626-83cb-470760bd86c3" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "\begin{bmatrix}5 & 1 \\ 1 & 3\end{bmatrix}" :db/id 17592186407537}] :answer-field/correct {:answer/id #uuid "1f090535-e10a-5c59-9a51-2d2aae1cbc9b" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "\begin{bmatrix}-5 & 2 \\ 2 & -2\end{bmatrix}" :db/id 17592186407523} :answer-field/id #uuid "a49b921e-a620-50dc-993e-f6b1a37ca3f6" :answer-field/key "selection" :answer-field/type {:db/id 17592186045493 :db/ident :answer-field.type/radio} :db/id 17592186407546}] :question/difficulty {:db/id 17592186045487 :db/ident :question.difficulty/moderate} :question/problem "Suppose that

$\,$ ${v}_{1}=\begin{bmatrix}1 \\ 2\end{bmatrix}\,$ and $\,{v}_{2}=\begin{bmatrix}-2 \\ 1\end{bmatrix}$

are eigenvectors of a $2\times 2$ symmetric matrix $A$ that correspond to the eigenvalues ${\lambda }_{1}=-1$ and ${\lambda }_{2}=-6,$ respectively. Find the matrix $A.$" :question/worked-solution "The spectral decomposition of a $2\times 2$ symmetric matrix $A$ is given by

$$
A={\lambda }_{1}{u}_{1}\cdot {u}_{1}^{T}+{\lambda }_{2}{u}_{2}\cdot {u}_{2}^{T},
$$

where ${u}_{1}$ and ${u}_{2}$ are orthonormal eigenvectors of $A$ corresponding to the eigenvalues ${\lambda }_{1}$ and ${\lambda }_{2},$ respectively.

First, let's normalize our eigenvectors:

$$
\begin{aligned}{u}_{1} & =\frac{{v}_{1}}{‖{v}_{1}‖}=\frac{1}{\sqrt{5}}\begin{bmatrix}1 \\ 2\end{bmatrix} \\ {u}_{2} & =\frac{{v}_{2}}{‖{v}_{2}‖}=\frac{1}{\sqrt{5}}\begin{bmatrix}-2 \\ 1\end{bmatrix}\end{aligned}
$$

Therefore, we have

$$
\begin{aligned}A & ={\lambda }_{1}{u}_{1}{u}_{1}^{T}+{\lambda }_{2}{u}_{2}{u}_{2}^{T} \\  & =(-1)\cdot \frac{1}{\sqrt{5}}\begin{bmatrix}1 \\ 2\end{bmatrix}\cdot \frac{1}{\sqrt{5}}\begin{bmatrix}1 & 2\end{bmatrix}+(-6)\cdot \frac{1}{\sqrt{5}}\begin{bmatrix}-2 \\ 1\end{bmatrix}\cdot \frac{1}{\sqrt{5}}\begin{bmatrix}-2 & 1\end{bmatrix} \\  & =(-1)\cdot \frac{1}{5}\begin{bmatrix}1 \\ 2\end{bmatrix}\begin{bmatrix}1 & 2\end{bmatrix}+(-6)\cdot \frac{1}{5}\begin{bmatrix}-2 \\ 1\end{bmatrix}\begin{bmatrix}-2 & 1\end{bmatrix} \\  & =\frac{1}{5}((-1)\cdot \begin{bmatrix}1 \\ 2\end{bmatrix}\begin{bmatrix}1 & 2\end{bmatrix}+(-6)\cdot \begin{bmatrix}-2 \\ 1\end{bmatrix}\begin{bmatrix}-2 & 1\end{bmatrix}) \\  & =\frac{1}{5}((-1)\cdot \begin{bmatrix}1 & 2 \\ 2 & 4\end{bmatrix}+(-6)\cdot \begin{bmatrix}4 & -2 \\ -2 & 1\end{bmatrix}) \\  & =\frac{1}{5}\begin{bmatrix}-25 & 10 \\ 10 & -10\end{bmatrix} \\  & =\begin{bmatrix}-5 & 2 \\ 2 & -2\end{bmatrix}.\end{aligned}
$$"} {:answer-field/choices [{:answer/id #uuid "1556dc1b-0c8b-54e0-a340-18371f592ed3" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "\frac{1}{\sqrt{5}}\begin{bmatrix}4 & -2 \\ -2 & 1\end{bmatrix}" :db/id 17592186407520} {:answer/id #uuid "286d06a8-1050-59ed-a665-558d840c2aae" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "\sqrt{5}\begin{bmatrix}4 & -2 \\ -2 & 1\end{bmatrix}" :db/id 17592186407525} {:answer/id #uuid "d6effcc8-e643-5b20-9090-b3855faacab9" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "\frac{1}{5}\begin{bmatrix}2 & -1 \\ -1 & 1\end{bmatrix}" :db/id 17592186407541} {:answer/id #uuid "e9f4f75f-447a-5e0c-a1d6-feae985a30a3" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "\begin{bmatrix}2 & -1 \\ -1 & 1\end{bmatrix}" :db/id 17592186407543} {:answer/id #uuid "f93a6cf9-78b6-546d-ba88-361fc48a056a" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "\frac{1}{5}\begin{bmatrix}4 & -2 \\ -2 & 1\end{bmatrix}" :db/id 17592186407544}] :answer-field/correct {:answer/id #uuid "f93a6cf9-78b6-546d-ba88-361fc48a056a" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "\frac{1}{5}\begin{bmatrix}4 & -2 \\ -2 & 1\end{bmatrix}" :db/id 17592186407544} :answer-field/id #uuid "ebade115-5b0c-52d7-94cc-8ec9e5babad9" :answer-field/key "selection" :answer-field/type {:db/id 17592186045493 :db/ident :answer-field.type/radio} :db/id 17592186407549} {:answer/id #uuid "1556dc1b-0c8b-54e0-a340-18371f592ed3" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "\frac{1}{\sqrt{5}}\begin{bmatrix}4 & -2 \\ -2 & 1\end{bmatrix}" :db/id 17592186407520} {:answer/id #uuid "286d06a8-1050-59ed-a665-558d840c2aae" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "\sqrt{5}\begin{bmatrix}4 & -2 \\ -2 & 1\end{bmatrix}" :db/id 17592186407525} {:answer/id #uuid "d6e