b056-b8008595ed25" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "\begin{bmatrix}-5 & 6 \\ 6 & -3\end{bmatrix}" :db/id 17592186407540}] :answer-field/correct {:answer/id #uuid "6d264661-257d-5c8a-8684-122b5c0a6807" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "\begin{bmatrix}-5 & 6 \\ 6 & 0\end{bmatrix}" :db/id 17592186407531} :answer-field/id #uuid "d1092e23-b9a3-5556-b0d1-0745f95be4b9" :answer-field/key "selection" :answer-field/type {:db/id 17592186045493 :db/ident :answer-field.type/radio} :db/id 17592186407548} {:answer/id #uuid "16877fa0-d3a3-5da8-ba77-c7e71244a7c0" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "\begin{bmatrix}0 & -6 \\ -6 & 4\end{bmatrix}" :db/id 17592186407521} {:answer/id #uuid "6d264661-257d-5c8a-8684-122b5c0a6807" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "\begin{bmatrix}-5 & 6 \\ 6 & 0\end{bmatrix}" :db/id 17592186407531} {:answer/id #uuid "9555f6b0-dd96-561e-b956-a28b10613e7e" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "\begin{bmatrix}-8 & 6 \\ 6 & -3\end{bmatrix}" :db/id 17592186407535} {:answer/id #uuid "ad0b779d-af50-58f8-97aa-dd75027108dd" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "\begin{bmatrix}5 & -6 \\ -6 & -4\end{bmatrix}" :db/id 17592186407536} {:answer/id #uuid "d6231cbd-de79-555a-b056-b8008595ed25" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "\begin{bmatrix}-5 & 6 \\ 6 & -3\end{bmatrix}" :db/id 17592186407540} {:activity/expected-seconds 780.0 :activity/first-step {:db/id 17592186162849} :activity/id #uuid "22c8da45-56d1-5645-85df-aa94cccb29d8" :activity/scope {:db/id 17592186049849 :topic/id #uuid "1887f465-a1b8-5370-82f6-80e02b9d153a" :topic/math-academy-id 3120} :activity/steps [{:db/id 17592186162849 :step/content {:db/id 17592186163224 :tutorial/content "Suppose that $A$ is an $n\times n$ symmetric matrix over $\mathbb{R}.$ The **spectral theorem** states the following:

- The eigenvalues of $A$ are all real.

- The eigenvectors corresponding to *different* eigenvalues are orthogonal.

- The dimension of the eigenspace for each eigenvalue equals the multiplicity of that eigenvalue as a root of the characteristic polynomial.

- $A$ is orthogonally diagonalizable." :tutorial/id #uuid "5ecbbdd0-25a0-52ee-8f0c-987dcd8ba584" :tutorial/math-academy-id 4882 :tutorial/title "Introduction"} :step/id #uuid "84b2f14e-f6c7-5b6c-b6d7-19d4d7d71f71" :step/math-academy-id 30533 :step/next {:db/id 17592186162902}} {:db/id 17592186162902 :step/content {:db/id 17592186162013 :knowledge-point/canonical-example {:db/id 17592186161805 :question/id #uuid "6ae71f41-133f-50b6-a286-20ae7e2c3a9d" :question/math-academy-id "e-8291"} :knowledge-point/id #uuid "4c67d532-acd9-5231-a27f-d39084863e01" :knowledge-point/key-prerequisites [{:db/id 17592186048493}] :knowledge-point/questions [{:db/id 17592186162645} {:db/id 17592186162659} {:db/id 17592186365052} {:db/id 17592186366636} {:db/id 17592186366643} {:db/id 17592186366650} {:db/id 17592186366657} {:db/id 17592186411856} {:db/id 17592186478420}] :knowledge-point/title "Identifying True Statements Regarding the Spectral Theorem"} :step/id #uuid "95f72e96-f84b-5b21-a070-253638be57a8" :step/math-academy-id 30970 :step/next {:db/id 17592186162903}} {:db/id 17592186162903 :step/content {:db/id 17592186163243 :tutorial/content "We can write an $n\times n$ symmetric matrix $A$ in terms of a sum of products of its eigenvalues and eigenvectors.

Specifically, if $\mathbf{u}_i$ denotes an orthonormal eigenvector of $A$ corresponding to the eigenvalue $\lambda_i$ for $i=1,\ldots, n$, then

$$
A=\sum_{i=1}^n \lambda_i \mathbf{u}_i \mathbf{u}_i^T.
$$

Expressing a symmetric matrix $A$ in this way is called the **spectral decomposition** of $A.$

To demonstrate, let's find the spectral decomposition of the $2\times 2$ symmetric matrix $A,$ given by

![](images/40/408e7471e4ef788758d423af97f5683186f79192fd8933c350d45bb87f089875.svg)

The eigenvalues of $A$ are $\lambda_1 = 6$ and $\lambda_2 = -4,$ and the corresponding eigenvectors are

![](images/0c/0c22f7dd97e83c358cb3cef1fcc2db902d908140109334a8cf1c22b35b29c6d2.svg)

The spectral decomposition of $A$ is given by

$$
A =\sum_{i=1}^2 \lambda_i \mathbf{u}_i \mathbf{u}_i^T = \lambda_1 \mathbf u_1 \mathbf u_1^T + \lambda_2 \mathbf u_2 \mathbf u_2^T,
$$

where $\mathbf u_1$ and $\mathbf u_2$ are orthonormal eigenvectors of $A$ corresponding to $\lambda_1$ and $\lambda_2,$ respectively.

First, let's normalize our eigenvectors:

$$
\begin{aligned}{u}_{1} & =\frac{{v}_{1}}{‖{v}_{1}‖}=\frac{1}{\sqrt{10}}\begin{bmatrix}1 \\ 3\end{bmatrix} \\ {u}_{2} & =\frac{{v}_{2}}{‖{v}_{2}‖}=\frac{1}{\sqrt{10}}\begin{bmatrix}3 \\ -1\end{bmatrix}\end{aligned}
$$

Therefore, the spectral decomposition of $A$ is

$$
\begin{aligned}A & ={\lambda }_{1}{u}_{1}{u}_{1}^{T}+{\lambda }_{2}{u}_{2}{u}_{2}^{T} \\  & =6\cdot \frac{1}{\sqrt{10}}\begin{bmatrix}1 \\ 3\end{bmatrix}\cdot \frac{1}{\sqrt{10}}\begin{bmatrix}1 & 3\end{bmatrix}+(-4)\cdot \frac{1}{\sqrt{10}}\begin{bmatrix}3 \\ -1\end{bmatrix}\cdot \frac{1}{\sqrt{10}}\begin{bmatrix}3 & -1\end{bmatrix} \\  & =6\cdot \frac{1}{10}\begin{bmatrix}1 \\ 3\end{bmatrix}\cdot \begin{bmatrix}1 & 3\end{bmatrix}+(-4)\cdot \frac{1}{10}\begin{bmatrix}3 \\ -1\end{bmatrix}\cdot \begin{bmatrix}3 & -1\end{bmatrix} \\  & ={{6}_{⏟}}_{{\lambda }_{1}}\cdot {{\begin{bmatrix}\frac{1}{10} & \frac{3}{10} \\ \frac{3}{10} & \frac{9}{10}\end{bmatrix}}_{⏟}}_{{u}_{1}{u}_{1}^{T}}+{{(-4)}_{⏟}}_{{\lambda }_{2}}\cdot {{\begin{bmatrix}\frac{9}{10} & -\frac{3}{10} \\ -\frac{3}{10} & \frac{1}{10}\end{bmatrix}}_{⏟}}_{{u}_{2}{u}_{2}^{T}}.\end{aligned}
$$

In this decomposition, the matrix $\mathbf{u}_i \mathbf{u}_i^T$ is the orthogonal projection matrix that maps any $\mathbf x \in \mathbb R^2$ onto the subspace spanned by $\mathbf u_i.$" :tutorial/id #uuid "a90957e3-e4b9-548d-930b-e060c6b63859" :tutorial/math-academy-id 4973 :tutorial/title "The Spectral Decomposition of a Symmetric Matrix"} :step/id #uuid "8df507ec-4d53-59f1-b941-07907cd14b6f" :step/math-academy-id 30971 :step/next {:db/id 17592186162905}} {:db/id 17592186162904 :step/content {:db/id 17592186162014 :knowledge-point/canonical-example {:db/id 17592186161806 :question/id #uuid "d185ef42-c177-5217-99b7-b42d800f3385" :question/math-academy-id "e-8292"} :knowledge-point/id #uuid "84207049-12f7-514c-bfa2-51bce8631b41" :knowledge-point/key-prerequisites [{:db/id 17592186049489}] :knowledge-point/questions [{:db/id 17592186162646} {:db/id 17592186162662} {:db/id 17592186365059} {:db/id 17592186366670} {:db/id 17592186366677} {:db/id 17592186378058} {:db/id 17592186395038} {:db/id 17592186395045} {:db/id 17592186395052} {:db/id 17592186407552} {:db/id 17592186495170}] :knowledge-point/title "Finding a Projection Matrix That Orthogonally Projects a Vector to the Subspace Spanned by an Eigenvector"} :step/id #uuid "2a1d5d86-333c-5361-87ec-fd7766797988" :step/math-academy-id 30972} {:db/id 17592186162905 :step/content {:db/id 17592186162015 :knowledge-point/canonical-example {:db/id 17592186161807 :question/id #uuid "65b23c21-528f-5df7-a00c-8e2dce041276" :question/math-academy-id "e-8293"} :knowledge-point/id #uuid "785b09aa-1b82-5021-8b10-271a063cb916" :knowledge-point/questions [{:db/id 17592186162647} {:db/id 17592186162665} {:db/id 17592186366684} {:db/id 17592186375958} {:db/id 17592186378065} {:db/id 17592186395059} {:db/id 17592186395066} {:db/id 17592186395073} {:db/id 17592186407550} {:db/id 17592186407551} {:db/id 17592186407553}] :knowledge-point/title "Finding the Spectral Decomposition of a Symmetric Matrix"} :step/id #uuid "86248bdd-6a75-54cd-8196-8b333a64cac5" :step/math-academy-id 30973 :step/next {:db/id 17592186162904}}] :activity/title "The Spectral Theorem" :activity/type {:db/id 17592186045463 :db/ident :activity.type/lesson} :db/id 17592186162216} {:db/id 17592186162849 :step/content {:db/id 17592186163224 :tutorial/content "Suppose that $A$ is an $n\times n$ symmetric matrix over $\mathbb{R}.$ The **spectral theorem** states the following:

