186045498} :answer/value "\begin{bmatrix}-4 & 2 \\ 2 & 1\end{bmatrix}" :db/id 17592186378071} {:db/id 17592186495260 :step/content {:db/id 17592186395066 :question/answer-fields [{:answer-field/choices [{:answer/id #uuid "7d17ddb9-9738-5247-980d-6346f34ca3d6" :answer/type {:db/id 17592186045498} :answer/value "\begin{bmatrix}2 & 1 \\ 1 & 2\end{bmatrix}" :db/id 17592186395068} {:answer/id #uuid "9112c274-741d-5926-a7e8-28550395e3fe" :answer/type {:db/id 17592186045498} :answer/value "\begin{bmatrix}2 & 1 \\ 1 & -2\end{bmatrix}" :db/id 17592186395069} {:answer/id #uuid "a6833e0f-d872-5f84-8fad-2cd587942a79" :answer/type {:db/id 17592186045498} :answer/value "\begin{bmatrix}-2 & -1 \\ -1 & -2\end{bmatrix}" :db/id 17592186395070} {:answer/id #uuid "b6a1eeb9-2422-526b-996e-3116b894cad2" :answer/type {:db/id 17592186045498} :answer/value "\begin{bmatrix}2 & -1 \\ -1 & -2\end{bmatrix}" :db/id 17592186395071} {:answer/id #uuid "bb3216f5-0141-54bf-b967-4b7d4a78081b" :answer/type {:db/id 17592186045498} :answer/value "\begin{bmatrix}2 & -1 \\ -1 & 2\end{bmatrix}" :db/id 17592186395072}] :answer-field/correct {:db/id 17592186395068} :answer-field/id #uuid "da07241e-4465-5487-a804-a1f93208770d" :answer-field/key "selection" :answer-field/type {:db/id 17592186045493} :db/id 17592186395067}] :question/difficulty {:db/id 17592186045487} :question/id #uuid "4f741f54-e9ba-55b4-9c81-df73745d51c8" :question/math-academy-id "q-95724" :question/problem "Suppose that

$\,$ ${v}_{1}=\begin{bmatrix}1 \\ 1\end{bmatrix}\,$ and $\,{v}_{2}=\begin{bmatrix}-1 \\ 1\end{bmatrix}$

are eigenvectors of a $2\times 2$ symmetric matrix $A$ that correspond to the eigenvalues ${\lambda }_{1}=3$ and ${\lambda }_{2}=1,$ respectively. Find the matrix $A.$" :question/worked-solution "The spectral decomposition of a $2\times 2$ symmetric matrix $A$ is given by

$$
A={\lambda }_{1}{u}_{1}\cdot {u}_{1}^{T}+{\lambda }_{2}{u}_{2}\cdot {u}_{2}^{T},
$$

where ${u}_{1}$ and ${u}_{2}$ are orthonormal eigenvectors of $A$ corresponding to the eigenvalues ${\lambda }_{1}$ and ${\lambda }_{2},$ respectively.

First, let's normalize our eigenvectors:

$$
\begin{aligned}{u}_{1} & =\frac{{v}_{1}}{‖{v}_{1}‖}=\frac{1}{\sqrt{2}}\begin{bmatrix}1 \\ 1\end{bmatrix} \\ {u}_{2} & =\frac{{v}_{2}}{‖{v}_{2}‖}=\frac{1}{\sqrt{2}}\begin{bmatrix}-1 \\ 1\end{bmatrix}\end{aligned}
$$

Therefore, we have

$$
\begin{aligned}A & ={\lambda }_{1}{u}_{1}{u}_{1}^{T}+{\lambda }_{2}{u}_{2}{u}_{2}^{T} \\  & =3\cdot \frac{1}{\sqrt{2}}\begin{bmatrix}1 \\ 1\end{bmatrix}\cdot \frac{1}{\sqrt{2}}\begin{bmatrix}1 & 1\end{bmatrix}+1\cdot \frac{1}{\sqrt{2}}\begin{bmatrix}-1 \\ 1\end{bmatrix}\cdot \frac{1}{\sqrt{2}}\begin{bmatrix}-1 & 1\end{bmatrix} \\  & =3\cdot \frac{1}{2}\begin{bmatrix}1 \\ 1\end{bmatrix}\begin{bmatrix}1 & 1\end{bmatrix}+1\cdot \frac{1}{2}\begin{bmatrix}-1 \\ 1\end{bmatrix}\begin{bmatrix}-1 & 1\end{bmatrix} \\  & =\frac{1}{2}(3\cdot \begin{bmatrix}1 \\ 1\end{bmatrix}\begin{bmatrix}1 & 1\end{bmatrix}+1\cdot \begin{bmatrix}-1 \\ 1\end{bmatrix}\begin{bmatrix}-1 & 1\end{bmatrix}) \\  & =\frac{1}{2}(3\cdot \begin{bmatrix}1 & 1 \\ 1 & 1\end{bmatrix}+1\cdot \begin{bmatrix}1 & -1 \\ -1 & 1\end{bmatrix}) \\  & =\frac{1}{2}\begin{bmatrix}4 & 2 \\ 2 & 4\end{bmatrix} \\  & =\begin{bmatrix}2 & 1 \\ 1 & 2\end{bmatrix}.\end{aligned}
$$"} :step/id #uuid "dc9cbb5e-30fb-5f9a-8c8a-71b1f6f7926c"} {:db/id 17592186495253 :step/content {:db/id 17592186162662 :question/answer-fields [{:answer-field/choices [{:answer/id #uuid "07faab27-15f7-5312-8b38-59ad02f72521" :answer/type {:db/id 17592186045498} :answer/value "\frac{1}{\sqrt{26}}\begin{bmatrix}-1 & 5 \\ 5 & -25\end{bmatrix}" :db/id 17592186494338} {:answer/id #uuid "2f44ec68-5673-5d17-a202-807989a0d5ce" :answer/type {:db/id 17592186045498} :answer/value "\frac{1}{26}\begin{bmatrix}-1 & 5 \\ 5 & -25\end{bmatrix}" :db/id 17592186494410} {:answer/id #uuid "6c89eafa-421f-5962-9af4-946ba03a1964" :answer/type {:db/id 17592186045498} :answer/value "\sqrt{26}\begin{bmatrix}25 & -5 \\ -5 & 1\end{bmatrix}" :db/id 17592186494540} {:answer/id #uuid "8b205150-ffac-59f3-b8f8-30947cc22faa" :answer/type {:db/id 17592186045498} :answer/value "\frac{1}{\sqrt{26}}\begin{bmatrix}25 & -5 \\ -5 & 1\end{bmatrix}" :db/id 17592186494635} {:answer/id #uuid "9d276ed0-9aab-5f35-92de-cd40b3be996e" :answer/type {:db/id 17592186045498} :answer/value "\frac{1}{26}\begin{bmatrix}25 & -5 \\ -5 & 1\end{bmatrix}" :db/id 17592186494678}] :answer-field/correct {:db/id 17592186494678} :answer-field/id #uuid "27a49c53-38b7-5dbb-b5f4-f47add37c5d5" :answer-field/key "selection" :answer-field/type {:db/id 17592186045493} :db/id 17592186161264}] :question/difficulty {:db/id 17592186045487} :question/id #uuid "28c27a06-cd3b-5e3d-a19e-4b46b9bccd18" :question/math-academy-id "q-95714" :question/problem "Find the orthogonal projection matrix that maps $x\in {R}^{2}$ onto the subspace spanned by an eigenvector corresponding to the eigenvalue $\lambda =-10$ of the matrix $A=\begin{bmatrix}-9 & 5 \\ 5 & 15\end{bmatrix}.$" :question/worked-solution "The spectral decomposition of a $2\times 2$ symmetric matrix $A$ is given by

$$
A={\lambda }_{1}{u}_{1}\cdot {u}_{1}^{T}+{\lambda }_{2}{u}_{2}\cdot {u}_{2}^{T},
$$

where ${u}_{1}$ and ${u}_{2}$ are orthonormal eigenvectors of $A$ corresponding to the eigenvalues ${\lambda }_{1}$ and ${\lambda }_{2},$ respectively.

Moreover, ${u}_{i}\cdot {u}_{i}^{T}$ is the projection matrix corresponding to ${u}_{i}.$

First, we need to find an eigenvector that corresponds to $\lambda =-10.$ Computing $A-(-10)I,$ we get

$$
\begin{aligned}A+10I & =\begin{bmatrix}-9 & 5 \\ 5 & 15\end{bmatrix}+10\begin{bmatrix}1 & 0 \\ 0 & 1\end{bmatrix}=\begin{bmatrix}1 & 5 \\ 5 & 25\end{bmatrix}.\end{aligned}
$$

So, we have a system of linear equations with the augmented matrix $M$ which we reduce to row echelon form using Gaussian elimination, as follows:

$$
\begin{aligned}M & =\begin{bmatrix}1 & 5 & 0 \\ 5 & 25 & 0\end{bmatrix} & {R}_{2} & :={R}_{2}+(-5){R}_{1} \\  & ∼\begin{bmatrix}1 & 5 & 0 \\ 0 & 0 & 0\end{bmatrix}\end{aligned}
$$

The reduced matrix above has one pivot column (the $1$st one). Thus, ${x}_{2}$ is a free variable. From the first equation, we obtain ${x}_{1}=-5{x}_{2}.$ Hence, the general solution is

$$
\begin{bmatrix}-5{x}_{2} \\ {x}_{2}\end{bmatrix},\,{x}_{2}\in R.
$$

Therefore, setting ${x}_{2}=1,$ we get the eigenvector 

$$
v=\begin{bmatrix}-5 \\ 1\end{bmatrix},
$$

where $‖v‖=\sqrt{26}.$ Dividing $v$ by its norm, we obtain the normalized eigenvector: 

$$
u=\frac{v}{‖v‖}=\frac{1}{\sqrt{26}}\begin{bmatrix}-5 \\ 1\end{bmatrix}
$$

Finally, the required orthogonal projection matrix is given by

$$
\begin{aligned}u\cdot {u}^{T} & =\frac{1}{\sqrt{26}}\begin{bmatrix}-5 \\ 1\end{bmatrix}\cdot \frac{1}{\sqrt{26}}\begin{bmatrix}-5 & 1\end{bmatrix} \\  & =\frac{1}{26}\begin{bmatrix}-5 \\ 1\end{bmatrix}\cdot \begin{bmatrix}-5 & 1\end{bmatrix} \\  & =\frac{1}{26}\begin{bmatrix}25 & -5 \\ -5 & 1\end{bmatrix}.\end{aligned}
$$"} :step/id #uuid "cd9e99be-c8ca-50d9-aacd-09344ae9dae2" :step/next {:db/id 17592186495205}} {:answer-field/choices [{:answer/id #uuid "07faab27-15f7-5312-8b38-59ad02f72521" :answer/type {:db/id 17592186045498} :answer/value "\frac{1}{\sqrt{26}}\begin{bmatrix}-1 & 5 \\ 5 & -25\end{bmatrix}" :db/id 17592186494338} {:answer/id #uuid "2f44ec68-5673-5d17-a202-807989a0d5ce" :answer/type {:db/id 17592186045498} :answer/value "\frac{1}{26}\begin{bmatrix}-1 & 5 \\ 5 & -25\end{bmatrix}" :db/id 17592186494410} {:answer/id #uuid "6c89eafa-421f-5962-9af4-946ba03a1964" :answer/type {:db/id 17592186045498} :answer/value "\sqrt{26}\begin{bmatrix}25 & -5 \\ -5 & 1\end{bmatrix}" :db/id 17592186494540} {:answer/id #uuid "8b205150-ffac-59f3-b8f8-30947cc22faa" :answer/type {:db/id 17592186045498} :answer/value "\frac{1}{\sqrt{26}}\begin{bmatrix}25 & -5 \\ -5 & 1\end{bmatrix}" :db/id 17592186494635} {:answer/id #uuid "9d276ed0-9aab-5f35-92de-cd40b3be996e" :answer/type {:db/id 17592186045498} :answer/value "\frac{1}{26}\begin{bmatrix}25 & -5 \\ -5 & 1\end{bmatrix}" :db/id 17592186494678}] :answer-field/correct {:db/id 17592186494678} :answer-field/id #uuid "27a49c53-38b7-5dbb-b5f4-f47add37c5d5" :answer-field/key "selection" :answer-field/type {:db/id 17592186045493} :db/id 17592186161264} {:answer/id #uuid "07faab27-15f7-5312-8b38-59ad02f72521" :answer/type {:db/id 17592186045498} :answer/value "\frac{1}{\sqrt{26}}\begin{bmatrix}-1 & 5 \\ 5 & -25\end{bmatrix}" :db/id 17592186494338} {:answer/id #uuid "2f44ec68-5673-5d17-a202-807989a0d5ce" :answer/type {:db/id 17592186045498} :answer/value "\frac{1}{26}\begin{bmatrix}-1 & 5 \\ 5 & -25\end{bmatrix}" :db/id 17592186494410} {:answer/id #uuid "6c89eafa-421f-5962-9af4-946ba03a1964" :answer/type {:db/id 17592186045498} :answer/value "\sqrt{26}\begin{bmatrix}25 & -5 \\ -5 & 1\end{bmatrix}" :db/id 17592186494540} {:answer/id #uuid "8b205150-ffac-59f3-b8f8-30947cc22faa" :answer/type {:db/id 17592186045498} :answer/value "\frac{1}{\sqrt{26}}\begi