d 17592186045498 :db/ident :answer.type/math} :answer/value "{b}_{4}" :db/id 17592186313964}] :answer-field/correct {:answer/id #uuid "d2744563-6a41-5893-93d0-b2e699ab8ad1" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "{a}_{4}" :db/id 17592186313621} :answer-field/id #uuid "a57dbd7a-67e4-5987-80bd-70ad3b4f1683" :answer-field/key "selection" :answer-field/type {:db/id 17592186045493 :db/ident :answer-field.type/radio} :db/id 17592186314456} {:answer/id #uuid "16acd564-8bb4-5f1c-82c3-561b03904c9a" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "{a}_{4}+1" :db/id 17592186312131} {:answer/id #uuid "66e3422f-b052-5204-9993-f9b920cdcc5a" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "-{a}_{4}" :db/id 17592186312787} {:answer/id #uuid "ac180436-b1eb-556d-a68d-e61a5de3235e" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "-{b}_{4}" :db/id 17592186313323} {:answer/id #uuid "d2744563-6a41-5893-93d0-b2e699ab8ad1" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "{a}_{4}" :db/id 17592186313621} {:answer/id #uuid "f8d54e34-b41d-5b58-b634-d28765ea5ba2" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "{b}_{4}" :db/id 17592186313964} {:activity/expected-seconds 660.0 :activity/first-step {:db/id 17592186230068} :activity/id #uuid "3cf0aacb-2998-5924-ba68-b3d449d0e2b6" :activity/scope {:db/id 17592186050730 :topic/id #uuid "621645f8-2215-52be-860a-5546f675b962" :topic/math-academy-id 6709} :activity/steps [{:db/id 17592186230068 :step/content {:db/id 17592186230213 :tutorial/content "In applications, we often build new periodic signals by adding old ones together or scaling their amplitudes.
The Fourier series behaves well under these transformations, i.e., scaling and adding functions simply scales and adds their Fourier coefficients.

More precisely, let $f(x)$ and $g(x)$ be $2\pi$-periodic functions with Fourier series

$$
\begin{aligned}f(x) & ∼\frac{{a}_{0}}{2}+{\sum }_{n=1}^{\infty }({a}_{n}\operatorname{cos}⁡(nx)+{b}_{n}\operatorname{sin}⁡(nx)), \\ g(x) & ∼\frac{{c}_{0}}{2}+{\sum }_{n=1}^{\infty }({c}_{n}\operatorname{cos}⁡(nx)+{d}_{n}\operatorname{sin}⁡(nx)).\end{aligned}
$$

For constants $\alpha$ and $\beta,$ define

$$
h(x)=\alpha f(x)+\beta g(x).
$$

Then $h$ is also $2\pi$-periodic, and its Fourier series has the form

$$
h(x)\sim \dfrac{A_0}{2}+\sum_{n=1}^{\infty}\big(A_n\cos(nx)+B_n\sin(nx)\big),
$$

where the coefficients are obtained by combining the coefficients term-by-term:

- $A_0=\alpha a_0+\beta c_0$

- $A_n=\alpha a_n+\beta c_n$ for $n\ge 1$

- $B_n=\alpha b_n+\beta d_n$ for $n\ge 1$

Equivalently,

$$
\alpha f(x)+\beta g(x)
\sim
\dfrac{\alpha a_0+\beta c_0}{2}
+\sum_{n=1}^{\infty}\Big((\alpha a_n+\beta c_n)\cos(nx)+(\alpha b_n+\beta d_n)\sin(nx)\Big).
$$

**Watch out!** In this notation, 

- the *constant Fourier coefficient* is $A_0,$ while

- the *term* in the series is $\dfrac{A_0}{2}.$

Let's see a concrete example below." :tutorial/id #uuid "2f038c7e-1fe8-5c76-aec1-ee954aca0b35" :tutorial/math-academy-id 14625 :tutorial/title "Introduction"} :step/id #uuid "284d00c6-9424-5ab8-bc23-10c3e4386c31" :step/math-academy-id 600909 :step/next {:db/id 17592186230069}} {:db/id 17592186230069 :step/content {:db/id 17592186229173 :knowledge-point/canonical-example {:db/id 17592186228939 :question/id #uuid "cf8f2367-68af-5ef4-ac2e-5a73e37695d9" :question/math-academy-id "e-21803"} :knowledge-point/id #uuid "eb295d6c-62fe-59bc-a139-49785ac98f1f" :knowledge-point/key-prerequisites [{:db/id 17592186049306}] :knowledge-point/questions [{:db/id 17592186229728} {:db/id 17592186229729} {:db/id 17592186315013} {:db/id 17592186315014} {:db/id 17592186315015} {:db/id 17592186315016} {:db/id 17592186315017} {:db/id 17592186417677} {:db/id 17592186417678} {:db/id 17592186417682}] :knowledge-point/title "Using Linearity of Fourier Series"} :step/id #uuid "905bf9c8-d4bc-59ff-a667-9b328a2dd393" :step/math-academy-id 600910 :step/next {:db/id 17592186230070}} {:db/id 17592186230070 :step/content {:db/id 17592186230219 :tutorial/content "Some simple transformations of a periodic function have very predictable effects on its Fourier coefficients. First, we consider the effect of *adding a constant* (a *vertical shift*).

Assume $f$ has the Fourier series

$$
f(x)\sim \dfrac{a_0}{2}+\sum_{n=1}^{\infty}\big(a_n\cos(nx)+b_n\sin(nx)\big).
$$

If $h(x)=f(x)+C$ for a constant $C,$ then only the constant part of the Fourier series changes:

$$
h(x)\sim \dfrac{a_0+2C}{2}+\sum_{n=1}^{\infty}\big(a_n\cos(nx)+b_n\sin(nx)\big).
$$

So, the coefficients of the transformed series are

$$
a_0^{(h)}=a_0+2C,
\qquad
a_n^{(h)}=a_n,
\qquad
b_n^{(h)}=b_n.
$$

In the next slides, we will apply this rule to a concrete example." :tutorial/id #uuid "97a65ef1-7e05-5e99-9172-ee34abb62f01" :tutorial/math-academy-id 14645 :tutorial/title "Fourier Series Properties: Vertical Shifting"} :step/id #uuid "8f098fae-dff7-5015-8e23-680da9186bdf" :step/math-academy-id 600913 :step/next {:db/id 17592186230099}} {:db/id 17592186230071 :step/content {:db/id 17592186229174 :knowledge-point/canonical-example {:db/id 17592186228941 :question/id #uuid "848cc0af-b940-5ead-81ac-49cc6d2f4989" :question/math-academy-id "e-21805"} :knowledge-point/id #uuid "f30ca427-3074-56c3-828a-1327d7b172b0" :knowledge-point/key-prerequisites [{:db/id 17592186050647} {:db/id 17592186050962}] :knowledge-point/questions [{:db/id 17592186229719} {:db/id 17592186229720} {:db/id 17592186315018} {:db/id 17592186315019} {:db/id 17592186315020} {:db/id 17592186315021} {:db/id 17592186315022} {:db/id 17592186417679} {:db/id 17592186417680} {:db/id 17592186417681}] :knowledge-point/title "Identifying Effects of Vertical Shifting and Horizontal Reflection on Coefficients"} :step/id #uuid "adb6b87d-19f4-5dca-a59c-1ae6ecde0e28" :step/math-academy-id 600914 :step/next {:db/id 17592186230072}} {:db/id 17592186230072 :step/content {:db/id 17592186230218 :tutorial/content "When a $2\pi$-periodic function has symmetry, many of its Fourier coefficients must be zero. This can simplify Fourier series computations dramatically.

Assume $f(x)$ is $2\pi$-periodic and piecewise continuous on $[-\pi,\pi),$ with Fourier series

$$
f(x)\sim \dfrac{a_0}{2}+\sum_{n=1}^{\infty}\big(a_n\cos(nx)+b_n\sin(nx)\big).
$$

We will use the property that the integral of an odd function over a symmetric interval like $[-\pi, \pi]$ is always zero.

- If $f$ is an *even* function, meaning $f(-x)=f(x),$ then all sine coefficients $b_n$ must be zero.
This is because each $b_n$ is calculated from an integral of an *odd* function:

$$
b_n = \dfrac{1}{\pi}\int_{-\pi}^{\pi} \underbrace{f(x)}_{\text{even}} \, \underbrace{\sin(nx)}_{\text{odd}} \, \text{d}x = \dfrac{1}{\pi}\int_{-\pi}^{\pi} (\text{odd function})\,\text{d}x = 0.
$$

The Fourier series of an even function has *cosine terms only*:

$$
f(x)\sim \dfrac{a_0}{2}+\sum_{n=1}^{\infty}a_n\cos(nx)
$$

- If $f$ is an *odd* function, meaning $f(-x)=-f(x),$ then the constant and all cosine coefficients (both $a_0$ and $a_n$) must be zero.
This is because these coefficients are calculated from integrals of *odd* functions:

$$
a_n = \dfrac{1}{\pi}\int_{-\pi}^{\pi} \underbrace{f(x)}_{\text{odd}} \, \underbrace{\cos(nx)}_{\text{even}} \,\text{d}x = \dfrac{1}{\pi}\int_{-\pi}^{\pi} (\text{odd function})\,\text{d}x = 0 \quad (\text{for } n \ge 0).
$$

The Fourier series of an odd function has *sine terms only*:

$$
f(x)\sim \sum_{n=1}^{\infty}b_n\sin(nx)
$$

**Note:** We may use either $[-\pi,\pi)$ or $[-\pi,\pi]$ as the base interval. Including or excluding the endpoints does not affect the conclusions.

Let's see how this works on concrete examples below." :tutorial/id #uuid "dd9a59ae-0e83-5c4d-9b72-d4db4e1e202a" :tutorial/math-academy-id 14644 :tutorial/title "Fourier Series of Odd and Even Functions"} :step/id #uuid "814960c8-4765-557a-b06d-bfea6027ccc2" :step/math-academy-id 600917 :step/next {:db/id 17592186230073}} {:db/id 17592186230073 :step/content {:db/id 17592186229175 :knowledge-point/canonical-example {:db/id 17592186228940 :question/id #uuid "f43f5028-9314-5123-bbd8-85dc5c4a9b2b" :question/math-academy-id "e-21804"} :knowledge-point/id #uuid "532a73e6-e026-57c9-9bad-57cd2f75b6df" :knowledge-point/key-prerequisites [{:db/id 17592186048495} {:db/id 17592186050762}] :knowledge-point/questions [{:db/id 17592186229718} {:db/id 17592186229721} {:db/id 17592186315023} {:db/id 17592186315024} {:db/id 17592186315025} {:db/id 17592186385249} {:db/id 17592186397481} {:db/id 17592186417683}] :knowledge-point/title "Parity Recognition and Series Type"} :step/id #uuid "a90608fd-d95f-5ba7-bd63-3249845550d6" :step/math-academy-id 600918} {:db/id 17592186230099 :step/content {:db/id 17592186230239 :tutorial/content "Another simple transformation is *reflecting a function across the $y$-axis*.

Again, assume $f$ has the Fourier series

$$
f(x)\sim \dfrac{a_0}{2}+\sum_{n=1}^{\infty}\big(a_n\cos(nx)+b_n\sin(nx)\big).
$$

If $h(x)=f(-x),$ then cosine terms stay the same while sine terms change sign (because $\cos(nx)$ is even and $\sin(nx)$ is odd):

$$
h(x)\sim \dfrac{a_0}{2}+\sum_{n=1}^{\infty}\big(a_n\cos(nx)-b_n\sin(nx)\big).
$$

So, the coefficients of the transformed series are

$$
a_0^{(h)}=a_0,
\qquad
a_n^{(h)}=a_n,
\qquad
b_n^{(h)}=-b_n.
$$

Let's see how to apply this rule in practice on the next slides." :tutorial/id #uuid "71af7376-dcfe-571f-96a9-28dbce65cb76" :tutorial/math-academy-id 14855 :tutorial/title "Fourier Series Properties: Horizontal Reflection"} :step/id #uuid "06e400a8-93bf-593c-8c80-0ecb3f2ca60b" :step/math-academy-id 606272 :step/next {:db/id 17592186230071}}] :activity/title "Properties of Fourier Series" :activity/type {:db/id 17592186045463 :db/ident :activity.type/lesson} :db/id 17592186229265} {:db/id 17592186230068 :step/content {:db/id 17592186230213 :tutorial/content "In applications, we often build new periodic signals by adding old ones together or scaling their amplitudes.
