d "580533af-c13d-5e1c-8282-f0172709c7e1" :question/math-academy-id "e-153"} :knowledge-point/id #uuid "5e651cb4-ae24-5ac7-9c01-d90de562b155" :knowledge-point/key-prerequisites [{:db/id 17592186048835}] :knowledge-point/questions [{:db/id 17592186092716} {:db/id 17592186092717} {:db/id 17592186317198} {:db/id 17592186317199} {:db/id 17592186329811} {:db/id 17592186339015} {:db/id 17592186505746} {:db/id 17592186505779} {:db/id 17592186505842}] :knowledge-point/title "Estimating a Derivative From a Table Using a Forward Difference Approximation: Word Problem"} :step/id #uuid "7e8c5132-4661-56c0-9cc7-9cd625cd092f" :step/math-academy-id 682 :step/next {:db/id 17592186093334}} {:db/id 17592186093334 :step/content {:db/id 17592186092389 :knowledge-point/canonical-example {:db/id 17592186091958 :question/id #uuid "73818e0b-6f95-59a6-b1a7-672bbea8de86" :question/math-academy-id "e-154"} :knowledge-point/id #uuid "167f04f0-c08e-51d8-acfa-2c4660083e6a" :knowledge-point/questions [{:db/id 17592186092718} {:db/id 17592186092721} {:db/id 17592186297362} {:db/id 17592186317204} {:db/id 17592186317205} {:db/id 17592186317206} {:db/id 17592186505821} {:db/id 17592186505833}] :knowledge-point/title "Estimating a Derivative From a Graph Using a Forward Difference Approximation: Word Problem"} :step/id #uuid "712fc50f-c422-5419-9b82-fa1b3e7a4a00" :step/math-academy-id 684} {:activity/first-step {:db/id 17592186065149} :activity/id #uuid "633bad62-882e-5d8a-8c9d-aa13b14ea6e1" :activity/scope {:db/id 17592186050572 :topic/id #uuid "54b8c8a0-5bff-5a9f-9ca1-b046c38a20d9" :topic/math-academy-id 336} :activity/steps [{:db/id 17592186065149 :step/content {:db/id 17592186065362 :tutorial/content "Consider a curve $y=f(x)$ between two points $x=a$ and $x=b$. The **average rate of change** of $y=f(x)$ on the interval $x\in[a,b]$ is computed as follows:

$$
\dfrac{\Delta y}{\Delta x} = \dfrac{\text{change in}y}{\text{change in}x} = \dfrac{f(b)-f(a)}{b-a}
$$

Geometrically, the average rate of change represents the slope of the **secant line** which passes through $(a,f(a))$ and $(b,f(b))$.

![](images/2d/2d27bcc73d1bcb8545c058c06553e3f4bc80d5426a98f5bb90e4d4c0aef71108.png)

