b/id 17592186339380} {:answer/id #uuid "27b08816-b56d-56af-836b-7def3de74374" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "1" :db/id 17592186339471} {:answer/id #uuid "5f9046e3-4b75-5ec7-85ea-9c533359e0ed" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "-\frac{1}{5}" :db/id 17592186339978} {:answer/id #uuid "f5b4b4ce-5fc0-52c4-b98f-6b5653f025a0" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "\frac{1}{5}" :db/id 17592186341296}] :answer-field/correct {:answer/id #uuid "27b08816-b56d-56af-836b-7def3de74374" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "1" :db/id 17592186339471} :answer-field/id #uuid "5b4d815c-aca6-5656-b032-a10aa3df9d2c" :answer-field/key "selection" :answer-field/type {:db/id 17592186045493 :db/ident :answer-field.type/radio} :db/id 17592186341542}] :question/difficulty {:db/id 17592186045485 :db/ident :question.difficulty/easy} :question/problem "Given the vector $w=\begin{bmatrix}-2 \\ -4 \\ 2 \\ 1\end{bmatrix}$, find $‖-\frac{w}{5}‖.$" :question/worked-solution "Remember that we can factor a constant out of the norm, provided that we take the absolute value of the constant:

$$
‖kw‖=|k|\cdot ‖w‖
$$

Using this fact and the formula for the norm, we have

$$
\begin{aligned}‖-\frac{w}{5}‖ & =|-\frac{1}{5}|\cdot ‖w‖ \\  & =\frac{1}{5}\sqrt{{w}_{1}^{2}+{w}_{2}^{2}+{w}_{3}^{2}+{w}_{4}^{2}} \\  & =\frac{1}{5}\sqrt{(-2)^{2}+(-4)^{2}+{2}^{2}+{1}^{2}} \\  & =\frac{1}{5}\sqrt{4+16+4+1} \\  & =\frac{1}{5}\sqrt{25} \\  & =\frac{1}{5}\cdot 5 \\  & =1.\end{aligned}
$$"} {:db/id 17592186342161 :question/id #uuid "f10e4697-d07b-5a86-b37b-fc9b133ecd85" :question/math-academy-id "q-74136"} {:db/id 17592186392320 :question/id #uuid "7c79b45c-ccf1-5435-9a0b-cd68b68b15b1" :question/math-academy-id "q-39770"} {:db/id 17592186423587 :question/id #uuid "107fc4e1-2e72-5e57-99ba-69f5d3ed0685" :question/math-academy-id "q-139967"} {:db/id 17592186423592 :question/id #uuid "8cc596a5-8803-52b2-93a7-a243d5af26bc" :question/math-academy-id "q-74130"} {:db/id 17592186423600 :question/id #uuid "eca368ca-a4ba-5312-b178-c63c0431130b" :question/math-academy-id "q-74132"} {:db/id 17592186049274} {:db/id 17592186049811 :topic/difficulty 0.43082044120048707 :topic/encompasses [{:db/id 17592186428600 :encompassing/rationale "Initial Codex estimate from captured target-band crossing frequency. Selected account linear: 1 rises / 1 eligible passed source activities = 1.000000; nearest selected fraction = 1. Crossing activity numbers [1]; waits [1]. Separate account estimates: linear=1 (1/1). Selection: most observations, then lower weight, then account name; no averaging. Single-activity estimates included. Intervening target updates: False. Crossing frequency is the chosen practical estimate of encompassing coverage; a multi-band rise counts once. This does not interpret color steps as physical repetition units. Method: encompassing-report.md. Evidence: reference/mathacademy/encompassing-analysis-2026-10-11/frequency-fractions/linear-frequency-estimates.json, pair 2103->1374. All account evidence retained in the prepared import's selected-relationships.json." :encompassing/topic {:db/id 17592186050178} :encompassing/weight 1.0} {:db/id 17592186428601 :encompassing/rationale "Initial Codex estimate from captured target-band crossing frequency. Selected account linear: 1 rises / 3 eligible passed source activities = 0.333333; nearest selected fraction = 1/3. Crossing activity numbers [1]; waits [1]. Separate account estimates: linear=1/3 (1/3). Selection: 