$$
\begin{aligned}(w+v)\cdot (2u+3w) & =2(w\cdot u)+2(v\cdot u)+3(w\cdot w)+3(v\cdot w) \\  & =0+2(v\cdot u)+3(w\cdot w)+3(v\cdot w) \\  & =2(v\cdot u)+3(w\cdot w)+3(v\cdot w) \\  & =2(-4\cdot 5+(-2)\cdot 1+2\cdot (-3)+(-4)\cdot 3) \\  & +3(1\cdot 1+(-5)\cdot (-5)+2\cdot 2+2\cdot 2) \\  & +3(-4\cdot 1+(-2)\cdot (-5)+2\cdot 2+(-4)\cdot 2) \\  & =2(-40)+3(34)+3(2) \\  & =-80+102+6 \\  & =28.\end{aligned}
$$"} {:db/id 17592186326757 :question/id #uuid "53958151-65fe-5b1f-baf2-6a8fe65cad5b" :question/math-academy-id "q-39292"} {:db/id 17592186342172 :question/id #uuid "7987f3f5-5816-5c61-828f-b358bfeacc01" :question/math-academy-id "q-74180"} {:db/id 17592186342173 :question/id #uuid "f2fb4e33-4677-5c93-bb5f-be059ac583ba" :question/math-academy-id "q-74181"} {:db/id 17592186423652 :question/id #uuid "4593be43-7c77-5707-9a35-2724546ec310" :question/math-academy-id "q-74183"} {:db/id 17592186423655 :question/id #uuid "c0dbf414-70a0-5f19-8395-cf58e2c89041" :question/math-academy-id "q-74158"} {:db/id 17592186133772 :knowledge-point/canonical-example {:db/id 17592186133581 :question/id #uuid "8b0122e7-3500-50cf-8505-22970428dac6" :question/math-academy-id "e-5553"} :knowledge-point/id #uuid "8e02a242-6ef9-574a-be2a-2b68b35d761c" :knowledge-point/key-prerequisites [{:db/id 17592186048982}] :knowledge-point/questions [{:db/id 17592186134211 :question/id #uuid "c212d94f-4084-5eee-99e8-30c7436e1711" :question/math-academy-id "q-39337"} {:db/id 17592186134252 :question/id #uuid "69f9e8f7-7103-5d3a-9398-65c91081214b" :question/math-academy-id "q-40024"} {:db/id 17592186326800 :question/id #uuid "497a08fe-dee4-57e8-9ff7-a58214016282" :question/math-academy-id "q-40026"} {:db/id 17592186342176 :question/id #uuid "ce497845-60f6-5e53-8285-767276f5e787" :question/math-academy-id "q-74192"} {:db/id 17592186342178 :question/id #uuid "10336818-08ce-508e-8d26-edc0039fd630" :question/math-academy-id "q-74195"} {:db/id 17592186423656 :question/id #uuid "cc095c64-455d-525a-98ca-451d265b041d" :question/math-academy-id "q-39293"}] :knowledge-point/title "Determining Components of a Vector Orthogonal to Two Given Vectors"} {:db/id 17592186133581 :question/id #uuid "8b0122e7-3500-50cf-8505-22970428dac6" :question/math-academy-id "e-5553"} {:db/id 17592186048982} {:db/id 17592186134211 :question/id #uuid "c212d94f-4084-5eee-99e8-30c7436e1711" :question/math-academy-id "q-39337"} {:db/id 1759218