$$"} {:db/id 17592186157279 :knowledge-point/canonical-example {:db/id 17592186157083 :question/id #uuid "ef6f99c1-d605-5b09-983d-05837b464e07" :question/math-academy-id "e-7125"} :knowledge-point/id #uuid "50c12386-8f44-5a50-af97-25cb87ae649f" :knowledge-point/questions [{:db/id 17592186157796 :question/id #uuid "73504416-c19a-5e33-b851-c4642d48b55e" :question/math-academy-id "q-81070"} {:db/id 17592186157815 :question/id #uuid "839d2d76-4244-527c-b217-209b05997760" :question/math-academy-id "q-81619"} {:db/id 17592186375895 :question/id #uuid "6bf5f4a1-ca8d-5e1b-8821-c37755c3d6c6" :question/math-academy-id "q-128648"} {:db/id 17592186375902 :question/id #uuid "cafb8751-7d49-5d15-86e5-11d26dd6845d" :question/math-academy-id "q-128650"} {:db/id 17592186387950 :question/id #uuid "38bb30f4-3f50-5deb-9dfd-dd66eda5da6e" :question/math-academy-id "q-128651"} {:db/id 17592186394745 :question/id #uuid "3162dd1b-d14f-5acb-8bf4-e2a6647760d8" :question/math-academy-id "q-86774"} {:db/id 17592186417115 :question/id #uuid "374fa45c-c4d5-567c-b9a7-224e1a49c369" :question/math-academy-id "q-81617"} {:db/id 17592186417118 :question/id #uuid "8a2417dc-04ea-557d-96c5-c1417328c84b" :question/math-academy-id "q-86775"} {:db/id 17592186417318 :question/id #uuid "3183a560-83c2-5a40-b064-73f7caf64d8c" :question/math-academy-id "q-129255"} {:db/id 17592186417323 :question/id #uuid "b2254182-38ff-5dd2-aadf-edfe22921646" :question/math-academy-id "q-129256"} {:db/id 17592186417324 :question/id #uuid "b416b846-e38c-522b-bcdc-fa3137a09cdc" :question/math-academy-id "q-128652"} {:db/id 17592186506592 :question/id #uuid "dd8060ac-5133-5617-8826-8c5bef481505" :question/math-academy-id "q-81622"}] :knowledge-point/title "Simplifying a Statement Using the Distributive Property for Disjunctions"} {:db/id 17592186157083 :question/id #uuid "ef6f99c1-d605-5b09-983d-05837b464e07" :question/math-academy-id "e-7125"} {:db/id 17592186157796 :question/id #uuid "73504416-c19a-5e33-b851-c4642d48b55e" :questi