$$"} :step/id #uuid "4b98f3ca-9d65-5627-9573-4ba0b664bec7" :step/next {:db/id 17592186500442}} {:answer-field/choices [{:answer/id #uuid "0e338a7c-f5c5-55b6-800b-47f10296b1d7" :answer/type {:db/id 17592186045498} :answer/value "\frac{112}{729}" :db/id 17592186499686} {:answer/id #uuid "4673f4bc-028d-52bd-b6cb-43a313197f90" :answer/type {:db/id 17592186045498} :answer/value "\frac{23}{1458}" :db/id 17592186499785} {:answer/id #uuid "60d5eb82-e934-5a50-abfb-6bb988e212e5" :answer/type {:db/id 17592186045498} :answer/value "\frac{230}{729}" :db/id 17592186499844} {:answer/id #uuid "aa8b3642-18a5-59b9-ba90-c44b1dc2ff93" :answer/type {:db/id 17592186045498} :answer/value "\frac{130}{729}" :db/id 17592186499989} {:answer/id #uuid "b05849a6-fd14-5761-ac6a-f3df6f46c897" :answer/type {:db/id 17592186045498} :answer/value "\frac{113}{1458}" :db/id 17592186500007}] :answer-field/correct {:db/id 17592186499844} :answer-field/id #uuid "ecc71117-bad7-5cf6-bbde-8b45ac8873de" :answer-field/key "selection" :answer-field/type {:db/id 17592186045493} :db/id 17592186500274} {:answer/id #uuid "0e338a7c-f5c5-55b6-800b-47f10296b1d7" :answer/type {:db/id 17592186045498} :answer/value "\frac{112}{729}" :db/id 17592186499686} {:answer/id #uuid "4673f4bc-028d-52bd-b6cb-43a313197f90" :answer/type {:db/id 17592186045498} :answer/value "\frac{23}{1458}" :db/id 17592186499785} {:answer/id #uuid "60d5eb82-e934-5a50-abfb-6bb988e212e5" :answer/type {:db/id 17592186045498} :answer/value "\frac{230}{729}" :db/id 17592186499844} {:answer/id #uuid "aa8b3642-18a5-59b9-ba90-c44b1dc2ff93" :answer/type {:db/id 17592186045498} :answer/value "\frac{130}{729}" :db/id 17592186499989} {:answer/id #uuid "b05849a6-fd14-5761-ac6a-f3df6f46c897" :answer/type {:db/id 17592186045498} :answer/value "\frac{113}{1458}" :db/id 17592186500007} {:db/id 17592186500442 :step/content {:db/id 17592186442324 :question/answer-fields [{:answer-field/choices [{:answer/id #uuid "da4529e7-604e-506b-adaa-ff85312c20f9" :answer/type {:db/