$$"} :step/id #uuid "cc39bcea-e4ea-5193-946b-a894508db75a"} {:answer-field/choices [{:answer/id #uuid "095360e1-dd96-5383-931f-a201eff47a39" :answer/type {:db/id 17592186045498} :answer/value "F(x)=1-\frac{1}{1-{e}^{x}}" :db/id 17592186419857} {:answer/id #uuid "170a0edf-da7f-5652-903d-c47b4ac8c342" :answer/type {:db/id 17592186045498} :answer/value "F(x)=1+\frac{1}{1+{e}^{x}}" :db/id 17592186419864} {:answer/id #uuid "3a8d1627-2737-5252-95ce-1a7d32a52868" :answer/type {:db/id 17592186045498} :answer/value "F(x)=1-\frac{1}{1+{e}^{x}}" :db/id 17592186419871} {:answer/id #uuid "4b0ae796-f204-5f28-ae72-68cb7f93938e" :answer/type {:db/id 17592186045498} :answer/value "F(x)=1+\frac{1}{(1+{e}^{x})^{2}}" :db/id 17592186419873} {:answer/id #uuid "cfec970b-e672-5e0e-a27f-c56e83e7f7ee" :answer/type {:db/id 17592186045498} :answer/value "F(x)=1-\frac{1}{(1+{e}^{x})^{2}}" :db/id 17592186419918}] :answer-field/correct {:db/id 17592186419918} :answer-field/id #uuid "f84d8dbb-e4a3-55af-a310-662430392d90" :answer-field/key "selection" :answer-field/type {:db/id 17592186045493} :db/id 17592186419940} {:answer/id #uuid "095360e1-dd96-5383-931f-a201eff47a39" :answer/type {:db/id 17592186045498} :answer/value "F(x)=1-\frac{1}{1-{e}^{x}}" :db/id 17592186419857} {:answer/id #uuid "170a0edf-da7f-5652-903d-c47b4ac8c342" :answer/type {:db/id 17592186045498} :answer/value "F(x)=1+\frac{1}{1+{e}^{x}}" :db/id 17592186419864} {:answer/id #uuid "3a8d1627-2737-5252-95ce-1a7d32a52868" :answer/type {:db/id 17592186045498} :answer/value "F(x)=1-\frac{1}{1+{e}^{x}}" :db/id 17592186419871} {:answer/id #uuid "4b0ae796-f204-5f28-ae72-68cb7f93938e" :answer/type {:db/id 17592186045498} :answer/value "F(x)=1+\frac{1}{(1+{e}^{x})^{2}}" :db/id 17592186419873} {:answer/id #uuid "cfec970b-e672-5e0e-a27f-c56e83e7f7ee" :answer/type {:db/id 17592186045498} :answer/value "F(x)=1-\frac{1}{(1+{e}^{x})^{2}}" :db/id 17592186419918} {:activity/course {:db/id 17592186046659} :activity/first-step {:db/id 17592186501258} 