$$"} :step/id #uuid "1943e8ec-2299-593e-84f2-5af6e5f545e6" :step/next {:db/id 17592186501283}} {:db/id 17592186501258 :step/content {:db/id 17592186501183 :question/answer-fields [{:answer-field/choices [{:answer/id #uuid "1c522a9a-a340-5730-935a-e853421c44ca" :answer/type {:db/id 17592186045498} :answer/value "\frac{75-2x}{75}" :db/id 17592186500525} {:answer/id #uuid "49f3c406-0b5e-5522-a240-414ac7e0f856" :answer/type {:db/id 17592186045498} :answer/value "\frac{{x}^{2}-25}{75}" :db/id 17592186500615} {:answer/id #uuid "887364d0-5dcf-5d1a-9cb5-af1322ef590e" :answer/type {:db/id 17592186045498} :answer/value "\frac{75-{x}^{2}}{75}" :db/id 17592186500754} {:answer/id #uuid "b55dc857-62d1-5ed0-85ee-8b7c291b0260" :answer/type {:db/id 17592186045498} :answer/value "\frac{1}{75}x" :db/id 17592186500845} {:answer/id #uuid "f364853a-396b-5d86-bdbe-5ffe621626d8" :answer/type {:db/id 17592186045498} :answer/value "\frac{1}{75}{x}^{2}" :db/id 17592186500984}] :answer-field/correct {:db/id 17592186500615} :answer-field/id #uuid "94adf626-a400-5181-b287-7ccffcedb8aa" :answer-field/key "selection" :answer-field/type {:db/id 17592186045493} :db/id 17592186501085}] :question/difficulty {:db/id 17592186045485} :question/id #uuid "770dc96c-77d3-556b-b303-18d387043365" :question/math-academy-id "q-89606" :question/problem "Given that the random variable $X$ has the probability density function

$$
f(x)=\{\begin{aligned}\frac{2}{75}x,\, & 5\le x\le 10 \\ 0,\, & \text{otherwise}\end{aligned}
$$

its cumulative distribution function is 

$$
F(x)=\{\begin{aligned}0,\, & x<5 \\ h(x),\, & 5\le x\le 10 \\ 1,\, & x>10.\end{aligned}
