wer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "\frac{1}{6}" :db/id 17592186325843} {:answer/id #uuid "f8d2beef-eaea-5c96-adf4-c346ba078cbb" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "-\frac{1}{6}" :db/id 17592186326162}] :answer-field/correct {:answer/id #uuid "6c6d60ca-7ba6-582b-8ba8-aa6a2bb6f45a" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "\frac{1}{37}" :db/id 17592186324870} :answer-field/id #uuid "108e1ca7-51ee-54a2-986d-908f36b9ba57" :answer-field/key "selection" :answer-field/type {:db/id 17592186045493 :db/ident :answer-field.type/radio} :db/id 17592186326251} {:answer/id #uuid "2f0a06d8-2d1a-56c8-be6c-0de612626107" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "\frac{1}{35}" :db/id 17592186324346} {:answer/id #uuid "6c6d60ca-7ba6-582b-8ba8-aa6a2bb6f45a" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "\frac{1}{37}" :db/id 17592186324870} {:answer/id #uuid "86278f77-2ac1-53b5-bab8-a9ea417f8fd0" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "\frac{35}{6}" :db/id 17592186325108} {:answer/id #uuid "d75de039-1846-5a30-9cbb-9b88d55e855c" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "\frac{1}{6}" :db/id 17592186325843} {:answer/id #uuid "f8d2beef-eaea-5c96-adf4-c346ba078cbb" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "-\frac{1}{6}" :db/id 17592186326162} {:activity/expected-seconds 1140.0 :activity/first-step {:db/id 17592186134663} :activity/id #uuid "7dcd79bf-0e4f-5dab-b7c9-aeea97042511" :activity/scope {:db/id 17592186049811 :topic/id #uuid "157ebcd0-6389-529a-a695-53136d4482c5" :topic/math-academy-id 2103} :activity/steps [{:db/id 17592186134663 :step/content {:db/id 17592186135045 :tutorial/content "A set of vectors ${U}=\{ \mathbf{u}_1, \cdots, \mathbf{u}_p \}$ in $\mathbb{R}^n$ is an **orthogonal set** if each pair of distinct vectors from the set is orthogonal.

For example, let's consider the following set:

![](images/9b/9b5afbbe850cb936b16b177e0a1b42bdd94df9bdc5dd3830aadc0de328a2b0d8.svg)

If we denote the vectors in our set ${W}$ as $\{ \mathbf{w}_1, \mathbf{w}_2, \mathbf{w}_3 \},$ we can check that ${W}$ is orthogonal by showing that 

$$
\{\begin{aligned}{w}_{1}\cdot {w}_{2}=0 \\ {w}_{1}\cdot {w}_{3}=0 \\ {w}_{2}\cdot {w}_{3}=0.\end{aligned}
$$

Let's compute each dot product:

$$
\begin{aligned}{w}_{1}\cdot {w}_{2} & =\begin{bmatrix}3 \\ 1 \\ 1\end{bmatrix}\cdot \begin{bmatrix}-1 \\ 2 \\ 1\end{bmatrix}=3\cdot (-1)+1\cdot 2+1\cdot 1=0 & ✓ \\ {w}_{1}\cdot {w}_{3} & =\begin{bmatrix}3 \\ 1 \\ 1\end{bmatrix}\cdot \begin{bmatrix}-1 \\ -4 \\ 7\end{bmatrix}=3\cdot (-1)+1\cdot (-4)+1\cdot 7=0 & ✓ \\ {w}_{2}\cdot {w}_{3} & =\begin{bmatrix}-1 \\ 2 \\ 1\end{bmatrix}\cdot \begin{bmatrix}-1 \\ -4 \\ 7\end{bmatrix}=(-1)\cdot (-1)+2\cdot (-4)+1\cdot 7=0 & ✓\end{aligned}
$$

So indeed, ${W}$ is an orthogonal set.

If an orthogonal set is also a basis, then we call it an **orthogonal basis**. Here, $W$ is an orthogonal basis of $\mathbb{R}^3,$ because it contains three linearly independent (you can check this) orthogonal vectors." :tutorial/id #uuid "dd93c4b2-6ec7-5a9c-a669-7979210393dd" :tutorial/math-academy-id 3618 :tutorial/title "Introduction"} :step/id #uuid "86221c16-9568-5f86-9e0e-496ed4975fdb" :step/math-academy-id 20224 :step/next {:db/id 17592186134772}} {:db/id 17592186134664 :step/content {:db/id 17592186133781 :knowledge-point/canonical-example {:db/id 17592186133590 :question/id #uuid "4b092f86-cf53-51b4-9f79-b43d58c8b2e5" :question/math-academy-id "e-5563"} :knowledge-point/id #uuid "ed5c8af7-e617-5e8c-be01-45a26eb17d4d" :knowledge-point/key-prerequisites [{:db/id 17592186048849}] :knowledge-point/questions [{:db/id 17592186134215} {:db/id 17592186134283} {:db/id 17592186272106} {:db/id 17592186272107} {:db/id 17592186351223} {:db/id 17592186351423} {:db/id 17592186351542} {:db/id 17592186371133} {:db/id 17592186371167} {:db/id 17592186433153}] :knowledge-point/title "Determining Whether Sets are Orthonormal"} :step/id #uuid "b9bda0f3-170c-5249-ae0f-9df7c5ca80fa" :step/math-academy-id 20225 :step/next {:db/id 17592186134665}} {:db/id 17592186134665 :step/content {:db/id 17592186133782 :knowledge-point/canonical-example {:db/id 17592186133591 :question/id #uuid "af1ca39e-5cb7-5a93-b88f-0ff86a563bc6" :question/math-academy-id "e-5564"} :knowledge-point/id #uuid "26f8f84c-bb94-5f3c-a78e-343f9c0c1b1a" :knowledge-point/key-prerequisites [{:db/id 17592186048445}] :knowledge-point/questions [{:db/id 17592186134220} {:db/id 17592186134280} {:db/id 17592186272108} {:db/id 17592186326826} {:db/id 17592186326836} {:db/id 17592186351544} {:db/id 17592186351545} {:db/id 17592186370894} {:db/id 17592186433149}] :knowledge-point/title "Extending a Set to Form an Orthogonal Basis"} :step/id #uuid "41f3017e-1bb3-5259-a7d8-a79e20fdc3e7" :step/math-academy-id 20226 :step/next {:d