46c7-7f57-5adc-8acb-ea91958d8725" :knowledge-point/title "Finding a Quadratic Taylor Polynomial"}] :question/problem "Determine the quadratic Taylor polynomial for the function of two variables 
$f(x,y) = \cos(x+y)$
about the point $(0,0).$" :question/worked-solution "If the function $f(x,y)$ is twice differentiable at $(x,y) = (0,0),$ then the quadratic Taylor polynomial of $f$ about $(0,0)$ is given by

$$
\begin{aligned}f(x,y) & ≈\overset{\text{Linear approximation}}{\overset{⏞}{f(0,0)+{f}_{x}(0,0)\cdot x+{f}_{y}(0,0)\cdot y}} \\  & \,\,+{{\frac{1}{2}({f}_{xx}(0,0)\cdot {x}^{2}+2{f}_{xy}(0,0)\cdot xy+{f}_{yy}(0,0)\cdot {y}^{2})}_{⏟}}_{\text{Quadratic part}}.\end{aligned}
$$

Now, we compute the terms of our Taylor polynomial.

- Calculating the value of the function, we have

$$
\begin{aligned}f(0,0) & =1.\end{aligned}
$$

- Calculating the first derivatives, we have the following:

$$
\begin{aligned}{f}_{x}(x,y) & =-\operatorname{sin}⁡(x+y), & \,{f}_{y}(x,y) & =-\operatorname{sin}⁡(x+y) \\ {f}_{x}(0,0) & =0, & \,{f}_{y}(0,0) & =0\end{aligned}
$$

- Calculating the second derivatives, we have the following:

$$
\begin{aligned}{f}_{xx}(x,y) & =-\operatorname{cos}⁡(x\,+\,y), & \,{f}_{xx}(0,0) & =-1 \\ {f}_{xy}(x,y) & =-\operatorname{cos}⁡(x\,+\,y), & \,{f}_{xy}(0,0) & =-1 \\ {f}_{yy}(x,y) & =-\operatorname{cos}⁡(x\,+\,y), & \,{f}_{yy}(0,0) & =-1\end{aligned}
$$

Therefore, the second-degree Taylor polynomial is given by

$$
\begin{aligned}f(x,y) & ≈1+0\cdot x+0\cdot y+\frac{1}{2}((-1)\cdot {x}^{2}+2(-1)\cdot xy+(-1)\cdot {y}^{2}) \\  & =1-\frac{1}{2}{x}^{2}-xy-\frac{1}{2}{y}^{2}.\end{aligned}
$$"} {:db/id 17592186049019} {:db/id 17592186198645 :question/id #uuid "3a23d317-8ce9-5c6e-8d7d-b18f5386617b" :question/math-academy-id "q-162992" :knowledge-point/_questions [{:db/id 17592186198434 :knowledge-point/id #uuid "e74c46c7-7f57-5adc-8acb-ea91958d8725" :knowledge-point/title "Finding a Quadratic Taylor Polynomial"}] :question/answer-fields [{:answer-field/choices [{:answer/id #uuid "1e54e1c9-205f-5069-a26e-144f61699b11" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "-2" :db/id 17592186278873} {:answer/id #uuid "53a1bca1-f8d6-5bc4-914c-05bf62ee4e7a" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "3" :db/id 17592186279353} {:answer/id #uuid "5ae60956-68d4-52a5-a560-be8be1ee1d39" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "-4" :db/id 17592186279431} {:answer/id #uuid "ea4c4625-0875-5288-88dc-8eec11112601" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "-8" :db/id 17592186280648} {:answer/id #uuid "fd2d11b4-8aaf-5097-aa76-39368cc3df6c" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "1" :db/id 17592186280808}] :answer-field/correct {:answer/id #uuid "1e54e1c9-205f-5069-a26e-144f61699b11" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "-2" :db/id 17592186278873} :answer-field/id #uuid "b152db49-e069-50cf-bae6-a47ce8602ca1" :answer-field/key "selection" :answer-field/type {:db/id 17592186045493 :db/ident :answer-field.type/radio} :db/id 17592186281146}] :question/difficulty {:db/id 17592186045485 :db/ident :question.difficulty/easy} :question/problem "For the function of two variables 
$f(x,y)={e}^{x-2y},$
the quadratic Taylor polynomial of $f$ about $(0,0)$ is given by

$$
f(x,y)=1+x+a\,y+\frac{1}{2}{x}^{2}+bxy+c{y}^{2}.
$$

Find the value of $a+b+c.$" :question/worked-solution "If the function $f(x,y)$ is twice differentiable at $(x,y)=(0,0),$ then the quadratic Taylor polynomial of $f$ about $(0,0)$ is given by

$$
\begin{aligned}f(x,y) & ≈\overset{\text{Linear approximation}}{\overset{⏞}{f(0,0)+{f}_{x}(0,0)\cdot x+{f}_{y}(0,0)\cdot y}} \\  & \,\,+{{\frac{1}{2}({f}_{xx}(0,0)\cdot {x}^{2}+2{f}_{xy}(0,0)\cdot xy+{f}_{yy}(0,0)\cdot {y}^{2})}_{⏟}}_{\text{Quadratic part}}.\end{aligned}
$$

Now, we compute the terms of our Taylor polynomial.

- Calculating the value of the function, we have

$$
\begin{aligned}f(0,0) & =1.\end{aligned}
$$

- Calculating the first derivatives, we have the following:

$$
\begin{aligned}{f}_{x}(x,y) & ={e}^{x-2y}, & \,{f}_{y}(x,y) & =-2{e}^{x-2y} \\ {f}_{x}(0,0) & =1, & \,{f}_{y}(0,0) & =-2\end{aligned}
$$

- Calculating the second derivatives, we have the following:

$$
\begin{aligned}{f}_{xx}(x,y) & ={e}^{x-2y}, & \,{f}_{xx}(0,0) & =1 \\ {f}_{xy}(x,y) & =-2{e}^{x-2y}, & \,{f}_{xy}(0,0) & =-2 \\ {f}_{yy}(x,y) & =4{e}^{x-2y}, & \,{f}_{yy}(0,0) & =4\end{aligned}
$$

Therefore, the second-degree Taylor polynomial is given by

$$
\begin{aligned}f(x,y) & ≈1+1\cdot x+(-2)\cdot y+\frac{1}{2}(1\cdot {x}^{2}+2(-2)\cdot xy+4\cdot {y}^{2}) \\  & =1+x+(-2)y+\frac{1}{2}{x}^{2}+(-2)xy+2{y}^{2}.\end{aligned}
$$

Finally,

$$
a+b+c=(-2)+(-2)+2=-2.
$$"} {:db/id 17592186198655 :question/id #uuid "6e6d1ba4-7501-5c84-a8cd-0bbe2d40c544" :question/math-academy-id "q-163113"} {:db/id 17592186281594 :question/id #uuid "40019177-315b-5f8c-afeb-29b9f1c22ad3" :question/math-academy-id "q-163088" :knowledge-point/_questions [{:db/id 17592186198434 :knowledge-point/id #uuid "e74c46c7-7f57-5adc-8acb-ea91958d8725" :knowledge-point/title "Finding a Quadratic Taylor Polynomial"}] :question/answer-fields [{:answer-field/choices [{:answer/id #uuid "03c1228e-2050-56a2-b557-e042a94e13ad" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "\frac{3}{2}" :db/id 17592186278617} {:answer/id #uuid "65bcf28f-9665-53c8-ad9d-52494b8f71a0" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "3" :db/id 17592186279517} {:answer/id #uuid "867433f2-e62a-5149-8f65-89ea1338e1a0" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "2" :db/id 17592186279791} {:answer/id #uuid "b0ef3ec5-904b-5bac-aaf1-4b133a5204b2" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "\frac{5}{4}" :db/id 17592186280159} {:answer/id #uuid "f8c774d0-0b8d-5b1a-aac1-8ea3a6aa6f9a" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "4" :db/id 17592186280777}] :answer-field/correct {:answer/id #uuid "867433f2-e62a-5149-8f65-89ea1338e1a0" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "2" :db/id 17592186279791} :answer-field/id #uuid "2b371790-c15b-5ab7-8f10-3eae5d762331" :answer-field/key "selection" :answer-field/type {:db/id 17592186045493 :db/ident :answer-field.type/radio} :db/id 17592186280912}] :question/difficulty {:db/id 17592186045485 :db/ident :question.difficulty/easy} :question/problem "For the function of two variables 
$f(x,y)={e}^{xy},$
the quadratic Taylor polynomial of $f$ about $(0,0)$ is given by

$$
f(x,y)=a+bxy.
$$

Find the value of $a+b.$" :question/worked-solution "If the function $f(x,y)$ is twice differentiable at $(x,y)=(0,0),$ then the quadratic Taylor polynomial of $f$ about $(0,0)$ is given by

$$
\begin{aligned}f(x,y) & ≈\overset{\text{Linear approximation}}{\overset{⏞}{f(0,0)+{f}_{x}(0,0)\cdot x+{f}_{y}(0,0)\cdot y}} \\  & \,\,+{{\frac{1}{2}({f}_{xx}(0,0)\cdot {x}^{2}+2{f}_{xy}(0,0)\cdot xy+{f}_{yy}(0,0)\cdot {y}^{2})}_{⏟}}_{\text{Quadratic part}}.\end{aligned}
$$

Now, we compute the terms of our Taylor polynomial.

- Calculating the value of the function, we have

$$
\begin{aligned}f(0,0) & =1.\end{aligned}
$$

- Calculating the first derivatives, we have the following:

$$
\begin{aligned}{f}_{x}(x,y) & =y{e}^{xy}, & \,{f}_{y}(x,y) & =x{e}^{xy} \\ {f}_{x}(0,0) & =0, & \,{f}_{y}(0,0) & =0\end{aligned}
$$

- Calculating the second derivatives, we have the following:

$$
\begin{aligned}{f}_{xx}(x,y) & ={y}^{2}{e}^{xy}, & \,{f}_{xx}(0,0) & =0 \\ {f}_{xy}(x,y) & =(1+xy){e}^{xy}, & \,{f}_{xy}(0,0) & =1 \\ {f}_{yy}(x,y) & ={x}^{2}{e}^{xy}, & \,{f}_{yy}(0,0) & =0\end{aligned}
$$

Therefore, the second-degree Taylor polynomial is given by

$$
\begin{aligned}f(x,y) & ≈1+0\cdot x+0\cdot y+\frac{1}{2}(0\cdot {x}^{2}+2(1)\cdot xy+0\cdot {y}^{2}) \\  & =1+1xy.\end{aligned}
$$

Finally,

$$
a+b=1+1=2.
$$"} {:db/id 17592186281595 :question/id #uuid "27445c9b-7e4a-5e28-a2d1-3fc7a72547b8" :question/math-academy-id "q-163089"} {:db/id 17592186281596 :question/id #uuid "c9afa446-cb01-5bd4-8e1a-c029b95460d7" :question/math-academy-id "q-163090"} {:db/id 17592186281599 :question/id #uuid "f950d98b-8d67-594b-b76b-e7454ed0e566" :question/math-academy-id "q-163095" :knowledge-point/_questions [{:db/id 17592186198434 :knowledge-point/id #uuid "e74c46c7-7f57-5adc-8acb-ea91958d8725" :knowledge-point/title "Finding a Quadratic Taylor Polynomial"}] :question/answer-fields [{:answer-field/choices [{:answer/id #uuid "12776ee4-bf66-52be-b94e-6da855692143" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "2" :db/id 17592186278760} {:answer/id #uuid "2992873e-5c72-56af-9b65-d007f9624836" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "8" :db/id 17592186278958} {:answer/id #uuid "3d837bf8-64a8-5ba8-b11f-d1e54f4538d5" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "6" :db/id 17592186279133} {:answer/id #uuid "b756c24d-21f1-5fd7-825b-a181399c4bcd" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "3" :db/id 17592186280201} {:answer/id #uuid "d732b216-6686-5d3d-b266-b392c5e5f514" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "4" :db/id 17592186280493}] :answer-field/correct {:answer/id #uuid "b756c24d-21f1-5fd7-825b-a181399c4bcd" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "3" :db/id 17592186280201} :answer-field/id #uuid "9241f691-955a-5b21-a8a2-fb377b58fa65" :answer-field/key "selection" :answer-field/type {:db/id 17592186045493 :db/ident :answer-field.type/radio} :db/id 17592186281096}] :question/difficulty {:db/id 17592186045485 :db/ident :question.difficulty/easy} :question/problem "For the function of two variables 
$f(x,y)={e}^{{x}^{2}+{y}^{2}},$
the quadratic Taylor polynomial of $f$ about $(0,0)$ is given by

$$
f(x,y)=a+b{x}^{2}+c{y}^{2}.
$$

Find the value of $a+b+c.$" :question/worked-solution "If the function $f(x,y)$ is twice differentiable at $(x,y)=(0,0),$ then the quadratic Taylor polynomial of $f$ about $(0,0)$ is given by

$$
\begin{aligned}f(x,y) & ≈\overset{\text{Linear approximation}}{\overset{⏞}{f(0,0)+{f}_{x}(0,0)\cdot x+{f}_{y}(0,0)\cdot y}} \\  & \,\,+{{\frac{1}{2}({f}_{xx}(0,0)\cdot {x}^{2}+2{f}_{xy}(0,0)\cdot xy+{f}_{yy}(0,0)\cdot {y}^{2})}_{⏟}}_{\text{Quadratic part}}.\end{aligned}
$$

Now, we compute the terms of our Taylor polynomial.

- Calculating the value of the function, we have

$$
\begin{aligned}f(0,0) & =1.\end{aligned}
$$

- Calculating the first derivatives, we have the following:

$$
\begin{aligned}{f}_{x}(x,y) & =2x{e}^{{x}^{2}+{y}^{2}}, & \,{f}_{y}(x,y) & =2y{e}^{{x}^{2}+{y}^{2}} \\ {f}_{x}(0,0) & =0, & \,{f}_{y}(0,0) & =0\end{aligned}
$$

- Calculating the second derivatives, we have the following:

$$
\begin{aligned}{f}_{xx}(x,y) & =2(1+2{x}^{2}){e}^{{x}^{2}+{y}^{2}}, & \,{f}_{xx}(0,0) & =2 \\ {f}_{xy}(x,y) & =4xy{e}^{{x}^{2}+{y}^{2}}, & \,{f}_{xy}(0,0) & =0 \\ {f}_{yy}(x,y) & =2(1+2{y}^{2}){e}^{{x}^{2}+{y}^{2}}, & \,{f}_{yy}(0,0) & =2\end{aligned}
$$

Therefore, the second-degree Taylor polynomial is given by

$$
\begin{aligned}f(x,y) & ≈1+0\cdot x+0\cdot y+\frac{1}{2}(2\cdot {x}^{2}+2(0)\cdot xy+2\cdot {y}^{2}) \\  & =1+1{x}^{2}+1{y}^{2}.\end{aligned}
$$

Finally,

$$
a+b+c=1+1+1=3.
$$"} {:db/id 17592186281604 :question/id #uuid "46cd9f15-1dee-5aee-b3d9-70903f558ae8" :question/math-academy-id "q-163111" :knowledge-point/_questions [{:db/id 17592186198434 :knowledge-point/id #uuid "e74c46c7-7f57-5adc-8acb-ea91958d8725" :knowledge-point/title "Finding a Quadratic Taylor Polynomial"}] :question/answer-fields [{:answer-field/choices [{:answer/id #uuid "2a163f00-423b-57e8-ae46-b60f111d48a1" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "\frac{3}{2}" :db/id 17592186278964} {:answer/id #uuid "3582f22b-3311-5a03-87b8-3529a0043ed8" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "0" :db/id 17592186279060} {:answer/id #uuid "4bc1b6c6-2219-5b6b-b6fb-06d4eeaed11a" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "3" :db/id 17592186279269} {:answer/id #uuid "7be2b338-9c19-55aa-9af1-1128dd120960" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "2" :db/id 17592186279698} {:answer/id #uuid "dd278181-66cd-5b8a-9eb0-5c8613158328" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "\frac{5}{4}" :db/id 17592186280542}] :answer-field/correct {:answer/id #uuid "2a163f00-423b-57e8-ae46-b60f111d48a1" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "\frac{3}{2}" :db/id 17592186278964} :answer-field/id #uuid "5c6589ef-e870-5ba4-8f44-69c9d5eac8cd" :answer-field/key "selection" :answer-field/type {:db/id 17592186045493 :db/ident :answer-field.type/radio} :db/id 17592186280992}] :question/difficulty {:db/id 17592186045485 :db/ident :question.difficulty/easy} :question/problem "For the function of two variables 
$f(x,y)=\operatorname{ln}⁡(x-y+1),$
the quadratic Taylor polynomial of $f$ about $(0,0)$ is given by

$$
f(x,y)=ax-y-\frac{1}{2}{x}^{2}+bxy+c{y}^{2}.
$$

Find the value of $a+b+c.$" :question/worked-solution "If the function $f(x,y)$ is twice differentiable at $(x,y)=(0,0),$ then the quadratic Taylor polynomial of $f$ about $(0,0)$ is given by

$$
\begin{aligned}f(x,y) & ≈\overset{\text{Linear approximation}}{\overset{⏞}{f(0,0)+{f}_{x}(0,0)\cdot x+{f}_{y}(0,0)\cdot y}} \\  & \,\,+{{\frac{1}{2}({f}_{xx}(0,0)\cdot {x}^{2}+2{f}_{xy}(0,0)\cdot xy+{f}_{yy}(0,0)\cdot {y}^{2})}_{⏟}}_{\text{Quadratic part}}.\end{aligned}
$$

Now, we compute the terms of our Taylor polynomial.

- Calculating the value of the function, we have

$$
\begin{aligned}f(0,0) & =0.\end{aligned}
$$

- Calculating the first derivatives, we have the following:

$$
\begin{aligned}{f}_{x}(x,y) & =\frac{1}{x-y+1}, & \,{f}_{y}(x,y) & =-\frac{1}{x-y+1} \\ {f}_{x}(0,0) & =1, & \,{f}_{y}(0,0) & =-1\end{aligned}
$$

- Calculating the second derivatives, we have the following:

$$
\begin{aligned}{f}_{xx}(x,y) & =-\frac{1}{(x-y+1)^{2}}, & \,{f}_{xx}(0,0) & =-1 \\ {f}_{xy}(x,y) & =\frac{1}{(x-y+1)^{2}}, & \,{f}_{xy}(0,0) & =1 \\ {f}_{yy}(x,y) & =-\frac{1}{(x-y+1)^{2}}, & \,{f}_{yy}(0,0) & =-1\end{aligned}
$$

Therefore, the second-degree Taylor polynomial is given by

$$
\begin{aligned}f(x,y) & ≈0+1\cdot x+(-1)\cdot y+\frac{1}{2}(-1\cdot {x}^{2}+2(1)\cdot xy+(-1)\cdot {y}^{2}) \\  & =1x-y-\frac{1}{2}{x}^{2}+1xy+(-\frac{1}{2}){y}^{2}.\end{aligned}
$$

Finally,

$$
a+b+c=1+1+(-\frac{1}{2})=\frac{3}{2}.
$$"} {:db/id 17592186432370 :question/id #uuid "046315b8-b9f7-5255-a5f6-6b97504a6e58" :question/math-academy-id "q-163094"} {:db/id 17592186432374 :question/id #uuid "f2c36de6-e7f2-52de-808d-79c266cdf722" :question/math-academy-id "q-163109" :knowledge-point/_questions [{:db/id 17592186198434 :knowledge-point/id #uuid "e74c46c7-7f57-5adc-8acb-ea91958d8725" :knowledge-point/title "Finding a Quadratic Taylor Polynomial"}] :question/answer-fields [{:answer-field/choices [{:answer/id #uuid "10b8dc7b-9ca0-57e4-95cf-ce295303bd77" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "5" :db/id 17592186432337} {:answer/id #uuid "426ee39a-6753-5cfc-b697-f79544216277" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "0" :db/id 17592186432344} {:answer/id #uuid "614bbaef-7919-554f-80d5-216b1c9e41ad" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "1" :db/id 17592186432349} {:answer/id #uuid "976864ab-946d-5ed5-a93b-3f163e2eea69" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "-1" :db/id 17592186432352} {:answer/id #uuid "f88f206b-7ef5-5e41-82c9-dd42ea25469f" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "2" :db/id 17592186432363}] :answer-field/correct {:answer/id #uuid "f88f206b-7ef5-5e41-82c9-dd42ea25469f" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "2" :db/id 17592186432363} :answer-field/id #uuid "d6d73795-71d5-5b5f-aef4-f1f6186ed7de" :answer-field/key "selection" :answer-field/type {:db/id 17592186045493 :db/ident :answer-field.type/radio} :db/id 17592186432369}] :question/difficulty {:db/id 17592186045485 :db/ident :question.difficulty/easy} :question/problem "For the function of two variables 
