\begin{aligned}f(a) & =-1, & \,{f}^{′}(a) & =\begin{bmatrix}1 & 0 & 1\end{bmatrix}, & \,{f}^{″}(a) & =\begin{bmatrix}3 & 0 & -1 \\ 0 & 1 & 0 \\ -1 & 0 & 2\end{bmatrix}\end{aligned}
