\begin{aligned}f(1,1,1) & ≈-1+\begin{bmatrix}1 & 0 & 1\end{bmatrix}\begin{bmatrix}1-1 \\ 1 \\ 1\end{bmatrix}+\frac{1}{2}{\begin{bmatrix}1-1 \\ 1 \\ 1\end{bmatrix}}^{T}\begin{bmatrix}3 & 0 & -1 \\ 0 & 1 & 0 \\ -1 & 0 & 2\end{bmatrix}\begin{bmatrix}1-1 \\ 1 \\ 1\end{bmatrix} \\  & =-1+\begin{bmatrix}1 & 0 & 1\end{bmatrix}\begin{bmatrix}0 \\ 1 \\ 1\end{bmatrix}+\frac{1}{2}{\begin{bmatrix}0 \\ 1 \\ 1\end{bmatrix}}^{T}\begin{bmatrix}3 & 0 & -1 \\ 0 & 1 & 0 \\ -1 & 0 & 2\end{bmatrix}\begin{bmatrix}0 \\ 1 \\ 1\end{bmatrix} \\  & =-1+1+\frac{1}{2}\begin{bmatrix}0 & 1 & 1\end{bmatrix}\begin{bmatrix}-1 \\ 1 \\ 2\end{bmatrix} \\  & =\frac{1}{2}(3) \\  & =\frac{3}{2}.\end{aligned}
$$"} {:db/id 17592186198678 :question/id #uuid "a0ff3e7e-07e5-5c92-aabb-370f248ce704" :question/math-academy-id "q-164611" :question/answer-fields [{:answer-field/choices [{:answer/id #uuid "08639b07-25fa-583e-a83f-d337dffebecf" :answer/type {:db/id 17592186045498} :answer/value "6" :db/id 17592186281761} {:answer/id #uuid "152ed58b-832e-5b30-8ecd-f7c2f04c36a7" :answer/type {:db/id 17592186045498} :answer/value "7" :db/id 17592186281887} {:answer/id #uuid "4577ccab-91a5-5a0a-ad8e-553e88e2a326" :answer/type {:db/id 17592186045498} :answer/value "3" :db/id 17592186282277} {:answer/id #uuid "84d9d89d-783c-5c61-8e59-033da0638e03" :answer/type {:db/id 17592186045498} :answer/value "5" :db/id 17592186282835} {:answer/id #uuid "fb6113b6-87b4-5fbe-ade6-6692083e0867" :answer/type {:db/id 17592186045498} :answer/value "4" :db/id 17592186283888}] :answer-field/correct {:db/id 17592186282277} :answer-field/id #uuid "e23126f6-69b8-59e0-8873-787033890983" :answer-field/key "selection" :answer-field/type {:db/id 17592186045493} :db/id 17592186284332}] :question/difficulty {:db/id 17592186045487} :question/problem "For the twice-differentiable function $f:{R}^{2}\to R,$ we have the following data:

$$
