\begin{aligned}f(1,1) & ≈0+\begin{bmatrix}1 & -1\end{bmatrix}\begin{bmatrix}1-\frac{\pi }{4} \\ 1-\frac{\pi }{4}\end{bmatrix}+\frac{1}{2}{\begin{bmatrix}1-\frac{\pi }{4} \\ 1-\frac{\pi }{4}\end{bmatrix}}^{T}\begin{bmatrix}-1 & 0 \\ 0 & -1\end{bmatrix}\begin{bmatrix}1-\frac{\pi }{4} \\ 1-\frac{\pi }{4}\end{bmatrix} \\  & =0+\frac{1}{2}{\begin{bmatrix}1-\frac{\pi }{4} \\ 1-\frac{\pi }{4}\end{bmatrix}}^{T}\begin{bmatrix}-(1-\frac{\pi }{4}) \\ -(1-\frac{\pi }{4})\end{bmatrix} \\  & =-\frac{1}{2}\cdot 2{(1-\frac{\pi }{4})}^{2} \\  & =-{(1-\frac{\pi }{4})}^{2}.\end{aligned}
$$"} {:db/id 17592186284524 :question/id #uuid "47346af3-1988-59d6-b35f-cf2ca4f49c94" :question/math-academy-id "q-164831"} {:db/id 17592186284530 :question/id #uuid "6aa91597-6ee2-53be-bdf3-8769a0188799" :question/math-academy-id "q-164858"} {:db/id 17592186284531 :question/id #uuid "476ff359-d053-5b12-8e13-351e9dc83e70" :question/math-academy-id "q-164859" :question/answer-fields [{:answer-field/choices [{:answer/id #uuid "5c52bfe3-c132-51f9-9f17-59b76eb15a8a" :answer/type {:db/id 17592186045498} :answer/value "-11" :db/id 17592186282471} {:answer/id #uuid "af8eb9d5-df46-5f33-9b42-1dcec1ba4a81" :answer/type {:db/id 17592186045498} :answer/value "-8" :db/id 17592186283206} {:answer/id #uuid "c8221ae2-715d-58b9-bc75-011e8e34610d" :answer/type {:db/id 17592186045498} :answer/value "-2" :db/id 17592186283439} {:answer/id #uuid "ca9a049b-ce44-5f95-85cb-8df2f5edcf7a" :answer/type {:db/id 17592186045498} :answer/value "1" :db/id 17592186283460} {:answer/id #uuid "e5217236-8877-51f1-a405-45114581cfc4" :answer/type {:db/id 17592186045498} :answer/value "-6" :db/id 17592186283688}] :answer-field/correct {:db/id 17592186283206} :answer-field/id #uuid "47e3460f-903c-51fc-a33d-e048585ab148" :answer-field/key "selection" :answer-field/type {:db/id 17592186045493} :db/id 17592186284050}] :question/difficulty {:db/id 17592186045486} :question/problem "For the twice-differentiable function $f:{R}^{3}\to R,$ we have the following data:

$$
