$$"} :step/id #uuid "ac4c51ea-2c80-5f4f-b061-1215e274de99" :step/next {:db/id 17592186430363}} {:answer-field/choices [{:answer/id #uuid "457a3842-15d8-5552-b245-a07a1675cac2" :answer/type {:db/id 17592186045498} :answer/value "2{x}_{3}" :db/id 17592186430278} {:answer/id #uuid "5cd9661f-8ecd-52f0-bb59-99f0d617f957" :answer/type {:db/id 17592186045498} :answer/value "{x}_{2}" :db/id 17592186430285} {:answer/id #uuid "aaf668ec-1209-510a-bec2-b439f7a0fc64" :answer/type {:db/id 17592186045498} :answer/value "{x}_{3}" :db/id 17592186430311}] :answer-field/correct {:db/id 17592186430285} :answer-field/id #uuid "111bbd61-ed5a-5717-8d1a-2107732df5dc" :answer-field/key "field-4" :answer-field/type {:db/id 17592186045494} :db/id 17592186430341} {:answer/id #uuid "457a3842-15d8-5552-b245-a07a1675cac2" :answer/type {:db/id 17592186045498} :answer/value "2{x}_{3}" :db/id 17592186430278} {:answer/id #uuid "5cd9661f-8ecd-52f0-bb59-99f0d617f957" :answer/type {:db/id 17592186045498} :answer/value "{x}_{2}" :db/id 17592186430285} {:answer/id #uuid "aaf668ec-1209-510a-bec2-b439f7a0fc64" :answer/type {:db/id 17592186045498} :answer/value "{x}_{3}" :db/id 17592186430311} {:answer-field/choices [{:answer/id #uuid "b020d76e-e1ef-5bcd-91cd-80bb99bd3362" :answer/type {:db/id 17592186045498} :answer/value "{x}_{2}" :db/id 17592186430312} {:answer/id #uuid "b66681db-9ca9-5aa2-be1a-2b2722e717f0" :answer/type {:db/id 17592186045498} :answer/value "{x}_{3}" :db/id 17592186430318} {:answer/id #uuid "e79293f1-0fa4-5fd9-a0c9-d75bdda1898a" :answer/type {:db/id 17592186045498} :answer/value "2{x}_{3}" :db/id 17592186430332}] :answer-field/correct {:db/id 17592186430318} :answer-field/id #uuid "290dfa59-387c-585b-835b-10031ed8be97" :answer-field/key "field-5" :answer-field/type {:db/id 17592186045494} :db/id 17592186430342} {:answer/id #uuid "b020d76e-e1ef-5bcd-91cd-80bb99bd3362" :answer/type {:db/id 17592186045498} :answer/value "{x}_{2}" :db/id 17592186430312} {:answer/id #uuid "b66681db-9ca9-5aa2-