{3}\end{bmatrix}" :db/id 17592186443367} {:answer/id #uuid "dd9ebd11-88f5-552e-b5e4-2988eb8b37a7" :answer/type {:db/id 17592186045498} :answer/value "\begin{bmatrix}-\frac{2}{3} \\ -\frac{1}{3} \\ \frac{2}{3}\end{bmatrix}" :db/id 17592186443377}] :answer-field/correct {:db/id 17592186443377} :answer-field/id #uuid "5c8bfdef-6f81-5a7f-8190-7d981c16e459" :answer-field/key "selection" :answer-field/type {:db/id 17592186045493} :db/id 17592186443393}] :question/difficulty {:db/id 17592186045487} :question/id #uuid "77278df4-e113-5900-8941-27a77a33d7c4" :question/math-academy-id "q-98696" :question/problem "$$
A=\begin{bmatrix}0 & 1 \\ -2 & -2 \\ -1 & 0\end{bmatrix},\,Σ=\begin{bmatrix}3 & 0 \\ 0 & 1 \\ 0 & 0\end{bmatrix},\,V=\begin{bmatrix}\frac{1}{\sqrt{2}} & -\frac{1}{\sqrt{2}} \\ \frac{1}{\sqrt{2}} & \frac{1}{\sqrt{2}}\end{bmatrix}
$$

Consider the matrices shown above. Given that $A=UΣ{V}^{T}$ is a singular value decomposition of $A,$ which of the following could be the $3$rd column of the matrix $U?$" :question/worked-solution "Recall that if  $A=UΣ{V}^{T}$ is a singular value decomposition of a $3\times 2$ matrix $A,$ then

- $Σ$ is a $3\times 2$ matrix with nonnegative elements on the main diagonal and zeroes outside the main diagonal,

- $U$ is an orthogonal $3\times 3$ matrix,

- $V$ is an orthogonal $2\times 2$ matrix.

From the matrix $Σ,$ we deduce that ${\sigma }_{1}=3$ and ${\sigma }_{2}=1.$
Also, the columns ${v}_{1}$ and ${v}_{2}$ of $V$ give us the right singular vectors of $A.$

Therefore, we can compute the $1$st and $2$nd columns of $U$ as follows:

- First, we compute ${u}_{1}:$

$$
\begin{aligned}{u}_{1} & =\frac{1}{{\sigma }_{1}}A{v}_{1} \\  & =\frac{1}{3}\begin{bmatrix}0 & 1 \\ -2 & -2 \\ -1 & 0\end{bmatrix}\begin{bmatrix}\frac{1}{\sqrt{2}} \\ \frac{1}{\sqrt{2}}\end{bmatrix} \\  & =\frac{1}{3}\begin{bmatrix}\frac{1}{\sqrt{2}} \\ -\frac{4}{\sqrt{2}} \\ -\frac{1}{\sqrt{2}}\end{bmatrix} \\  & =\begin{bmatrix}\frac{1}{3\sqrt{2}} \\ -\frac{4}{3\sqrt{2}} \\ -\frac{1}{3\sqrt{2}}\end{bmatrix}\end{aligned}
$$

- Then, we compute ${u}_{2}:$

$$
\begin{aligned}{u}_{2} & =\frac{1}{{\sigma }_{2}}A{v}_{2} \\  & =\frac{1}{1}\begin{bmatrix}0 & 1 \\ -2 & -2 \\ -1 & 0\end{bmatrix}\begin{bmatrix}-\frac{1}{\sqrt{2}} \\ \frac{1}{\sqrt{2}}\end{bmatrix} \\  & =\begin{bmatrix}\frac{1}{\sqrt{2}} \\ 0 \\ \frac{1}{\sqrt{2}}\end{bmatrix}\end{aligned}
$$

Since we do not have the third singular value, we can't use the same formula to find the third column of $U.$ But we know that $U$ must be orthogonal. Hence, we must find a vector 

$$
{u}_{3}=\begin{bmatrix}{x}_{1} \\ {x}_{2} \\ {x}_{3}\end{bmatrix}
$$

such that 

$$
\{\begin{aligned}{u}_{1}\cdot {u}_{3}=0 \\ {u}_{2}\cdot {u}_{3}=0,\end{aligned}\,‖{u}_{3}‖=1.
$$

Solving this system, which is equivalent to

$$
\{\begin{aligned}\frac{1}{3\sqrt{2}}{x}_{1}-\frac{4}{3\sqrt{2}}{x}_{2}-\frac{1}{3\sqrt{2}}{x}_{3}=0 \\ \frac{1}{\sqrt{2}}{x}_{1}+\frac{1}{\sqrt{2}}{x}_{3}=0\end{aligned}\,⟹\,\{\begin{aligned}{x}_{1}-4{x}_{2}-{x}_{3}=0 \\ {x}_{1}+{x}_{3}=0,\end{aligned}
$$

we get the nonzero normalized solution 

$$
{u}_{3}=\begin{bmatrix}-\frac{2}{3} \\ -\frac{1}{3} \\ \frac{2}{3}\end{bmatrix}.
$$

Finally, we construct the matrix $U:$

$$
U=\begin{bmatrix}\frac{1}{3\sqrt{2}} & \frac{1}{\sqrt{2}} & -\frac{2}{3} \\ -\frac{4}{3\sqrt{2}} & 0 & -\frac{1}{3} \\ -\frac{1}{3\sqrt{2}} & \frac{1}{\sqrt{2}} & \frac{2}{3}\end{bmatrix}
$$"} :step/id #uuid "46bb3e49-3990-5b69-ab08-fafc145eef1c" :step/next {:db/id 17592186443411}} {:db/id 17592186443410 :step/content {:db/id 17592186443407 :question/answer-fields [{:answer-field/choices [{:answer/id #uuid "521d6dc6-c306-5eff-a662-c8d5ca209cac" :answer/type {:db/id 17592186045498} :answer/value "2{x}_{2}" :db/id 17592186443340} {:answer/id #uuid "5a1282dd-cff4-5d9d-aea1-997f77fae849" :answer/type {:db/id 17592186045498} :answer/value "-2{x}_{2}" :db/id 17592186443343} {:answer/id #uuid "e6ac364e-730c-5977-844b-64abc957eff9" :answer/type {:db/id 17592186045498} :answer/value "{x}_{2}" :db/id 17592186443381}] :answer-field/correct {:db/id 17592186443343} :answer-field/id #uuid "01393794-e39b-5872-af64-efa4c600b9fc" :answer-field/key "field-4" :answer-field/type {:db/id 17592186045494} :db/id 17592186443388} {:answer-field/choices [{:answer/id #uuid "123f6db1-a64c-5351-af4f-43d4b9d652f0" :answer/type {:db/id 17592186045498} :answer/value "\frac{1}{\sqrt{5}}" :db/id 17592186443324} {:answer/id #uuid "37473ba7-f727-5d13-a1f4-d0e0252ed8b5" :answer/type {:db/id 17592186045498} :answer/value "0" :db/id 17592186443335} {:answer/id #uuid "482a2476-04ad-5ed6-a93d-a4c282bcffdf" :answer/type {:db/id 17592186045498} :answer/value "\frac{2}{\sqrt{5}}" :db/id 17592186443336} {:answer/id #uuid "b0772e32-b9f7-5716-b91d-a2a4ae968b35" :answer/type {:db/id 17592186045498} :answer/value "-\frac{2}{\sqrt{5}}" :db/id 17592186443362}] :answer-field/correct {:db/id 17592186443362} :answer-field/id #uuid "2d46592f-4a1b-598c-8e05-b401c0a291b3" :answer-field/key "field-6" :answer-field/type {:db/id 17592186045494} :db/id 17592186443390} {:answer-field/choices [{:answer/id #uuid "064fb74f-986e-5577-ad54-f76e5e51541d" :answer/type {:db/id 17592186045498} :answer/value "1" :db/id 17592186443318} {:answer/id #uuid "22f7b4a6-f46f-5b25-b769-5eb4b2fcfda8" :answer/type {:db/id 17592186045498} :answer/value "0" :db/id 17592186443327} {:answer/id #uuid "4b2fc124-b7bc-5a81-8d7e-feca608d3a9