$$

Next, we substitute the spherical polar coordinates into the function $f(x,y,z)={z}^{2}:$

$$
\begin{aligned}f(x,y,z) & =f(\rho \operatorname{cos}⁡\theta \operatorname{sin}⁡ϕ,\rho \operatorname{sin}⁡\theta \operatorname{sin}⁡ϕ,\rho \operatorname{cos}⁡ϕ) \\  & =(\rho \operatorname{cos}⁡ϕ) \\  & ={\rho }^{2}{cos}^{2}⁡ϕ\end{aligned}
$$

Therefore, using the change of variables formula, we obtain

$$
\begin{aligned}{∭}_{R}z\,\text{d}V & ={∭}_{Δ}{\rho }^{2}{cos}^{2}⁡ϕ\cdot {\rho }^{2}\operatorname{sin}⁡ϕ\,d\rho \,d\theta \,dϕ \\  & ={\int }_{0}^{\pi }{\int }_{0}^{2\pi }{\int }_{0}^{2}{\rho }^{4}{cos}^{2}⁡ϕ\operatorname{sin}⁡ϕ\,d\rho \,d\theta \,dϕ \\  & ={\int }_{0}^{\pi }{cos}^{2}⁡ϕ\operatorname{sin}⁡ϕ\,dϕ\cdot {\int }_{0}^{2\pi }d\theta \cdot {\int }_{0}^{2}{\rho }^{4}\,d\rho  \\  & ={[-\frac{1}{3}{cos}^{3}⁡ϕ]}_{ϕ=0}^{ϕ=\pi }\cdot [\theta ]_{\theta =0}^{\theta =2\pi }\cdot {[\frac{1}{5}{\rho }^{5}]}_{\rho =0}^{\rho =2}\,d\rho  \\  & =-\frac{1}{3}(-1-1)\cdot (2\pi -0)\cdot \frac{1}{5}(32-0) \\  & =\frac{2}{3}\cdot 2\pi \cdot \frac{32}{5} \\  & =\frac{128\pi }{15}\end{aligned}
$$"} :step/id #uuid "63749430-c9f6-5d26-a7e1-481aa4f8c432" :step/next {:db/id 17592186496363}} {:answer-field/choices [{:answer/id #uuid "0782d6f6-9606-57ec-9b7b-5f331ab47d02" :answer/type {:db/id 17592186045498} :answer/value "\frac{36\pi }{5}" :db/id 17592186495529} {:answer/id #uuid "844ba137-ce42-54c2-ad73-0a6795c8a9ff" :answer/type {:db/id 17592186045498} :answer/value "\frac{128\pi }{15}" :db/id 17592186495794} {:answer/id #uuid "d2e1bc82-3dca-5d12-a26c-e853c58acc81" :answer/type {:db/id 17592186045498} :answer/value "\frac{256\pi }{81}" :db/id 17592186495972} {:answer/id #uuid "d6f9f8b0-bd2d-567a-a334-e4d0096c528c" :answer/type {:db/id 17592186045498} :answer/value "\frac{81\pi }{8}" :db/id 17592186495983} {:answer/id #uuid "f5f5beda-e35c-5b36-a994-c61647e4e3cc" :answer/type {:db/id 17592186045498} :answer/value "\frac{64\pi }{27}" :db/id 17592186496046}] :answer-field/correct {:db/id 17592186495794} :answer-field/id #uuid "452ba3e6-053b-531a-8d38-cad4a5db1e22" :answer-field/key "selection" :answer-field/type {:db/id 17592186045493} :db/id 17592186496108} {:answer/id #uuid "0782d6f6-9606-57ec-9b7b-5f331ab47d02" :answer/type {:db/id 17592186045498} :answer/value "\frac{36\pi }{5}" :db/id 17592186495529} {:answer/id #uuid "844ba137-ce42-54c2-ad73-0a6795c8a9ff" :answer/type {:db/id 17592186045498} :answer/value "\frac{128\pi }{15}" :db/id 17592186495794} {:answer/id #uuid "d2e1bc82-3dca-5d12-a26c-e853c58acc81" :answer/type {:db/id 17592186045498} :answer/value "\frac{256\pi }{81}" :db/id 17592186495972} {:answer/id #uuid "d6f9f8b0-bd2d-567a-a334-e4d0096c528c" :answer/type {:db/id 17592186045498} :answer/value "\frac{81\pi }{8}" :db/id 17592186495983} {:answer/id #uuid "f5f5beda-e35c-5b36-a994-c61647e4e3cc" :answer/type {:db/id 17592186045498} :answer/value "\frac{64\pi }{27}" :db/id 17592186496046} {:db/id 17592186496363 :step/content {:db/id 17592186496308 :question/answer-fields [{:answer-field/choices [{:answer/id #uuid "021f15c9-f5ca-5fc3-8d40-1a3115937ceb" 