d "d15295c3-5868-57e4-8227-d3f5fdb96a55" :question/math-academy-id "q-80646"} {:db/id 17592186348435 :question/id #uuid "a1fd2252-93e6-52b7-b6db-b0208e66793d" :question/math-academy-id "q-80685"} {:db/id 17592186434984 :question/id #uuid "e309db36-c1df-54f7-9f6d-2cd23acc2d7b" :question/math-academy-id "q-80605"}] :knowledge-point/title "Finding the Critical Points of a Function"} {:db/id 17592186124216 :question/id #uuid "593eeb42-56b8-5177-8a9f-38d08a5186c1" :question/math-academy-id "e-12584" :knowledge-point/_canonical-example [{:db/id 17592186124653 :knowledge-point/id #uuid "045854fc-9cad-5005-a306-9550848e25df" :knowledge-point/title "Finding the Critical Points of a Function"}] :question/problem "Determine the critical points of $f(x,y) = x^3+y^3-3x^2y+9y.$" :question/worked-solution "The critical points of a multivariable function $f$ are the points $\mathbf a$ in the domain of $f$ such that $\boldsymbol f'(\mathbf a) =\mathbf 0^T$ or $\boldsymbol f'(\mathbf a)$ does not exist, where
![](images/e0/e044df6438236be737f2500fb5a96d8f7165822ca3db4b52247007a4a705e20f.svg)

In this case, the domain of $f$ is $\mathbb{R}^2,$ and the first partial derivatives of $f$ are

$$
\begin{aligned}\frac{∂f}{∂x} & =3{x}^{2}-6xy=3x(x-2y) \\ \frac{∂f}{∂y} & =3{y}^{2}-3{x}^{2}+9.\end{aligned}
$$



So, the first derivative of $f$ is
![](images/be/be42f33306c634f64bd5830c782a6a8b2cbb376bd124c2ca3edbbd5afc614d9c.svg)

To find the critical points, we need to find the points $(x,y) \in \mathbb{R}^2$ such that $\boldsymbol f'(x,y) = \mathbf{0}^T$ or $\boldsymbol f'(x,y)$ does not exist. Note that, in our case, $\boldsymbol f'(x,y)$ exists everywhere, so we just need to find the points where $\boldsymbol f'(x,y) = \mathbf{0}^T.$

Setting $\boldsymbol f'(x,y) = \mathbf{0}^T,$ we have the following system:

$$
\{\begin{aligned}3x(x-2y)=0 \\ 3{y}^{2}-3{x}^{2}+9=0\end{aligned}
$$

From the first equation, we obtain $x=0$ or $x=2y.$ Now, we substitute these values into the second equation.

- For $x=0,$ we get

$$
3y^2 - 3(0)^2 + 9 = 0 \qquad \Longrightarrow \qquad y^2 = -3,
$$

but this last equation has no real solution.

- For $x = 2y,$ we obtain

$$
3y^2 - 3(2y)^2 + 9 = 0 \qquad \Longrightarrow \qquad y = \pm 1.
$$

Substituting these values into $x = 2y,$ we get

$$
\begin{aligned}y=-1 & \,⟹\,x=2(-1)=-2 \\ y=1 & \,⟹\,x=2(1)=2.\end{aligned}
$$

Therefore, our system has two solutions, $(-2,-1)$ and $(2,1).$

In conclusion, $f$ has two critical points, $(-2,-1)$ and $(2,1).$ Note that since $\boldsymbol f'(\mathbf{x}) = \mathbf 0^T$ at these two points, they are also both stationary points."} {:db/id 17592186125004 :question/id #uuid "cc5f47ca-79fc-5729-9bb1-01328bbbf467" :question/math-academy-id "q-36622"} {:db/id 17592186125006 :question/id #uuid "5268fbe7-eec3-599a-9bb3-09780fd2d7a8" :question/math-academy-id "q-36635"} {:db/id 17592186235545 :question/id #uuid "234369d4-b826-5a50-9988-222596da5b56" :question/math-academy-id "q-168865"} {:db/id 17592186237887 :question/id #uuid "b5a6d7e9-e6c6-56f2-868d-1ad027ad7493" :question/math-academy-id "q-102328"} {:db/id 17592186238078 :question/id #uuid "97c7d2dc-74ac-59d1-8aae-33e46fb44258" :question/math-academy-id "q-103925"} {:db/id 17592186348429 :question/id #uuid "d15295c3-5868-57e4-8227-d3f5fdb96a55" :question/math-academy-id "q-80646"} {:db/id 17592186348435 :question/id #uuid "a1fd2252-93e6-52b7-b6db-b0208e66793d" :question/math-academy-id "q-80685"} {:db/id 17592186434984 :question/id #uuid "e309db36-c1df-54f7-9f6d-2cd23acc2d7b" :question/math-academy-id "q-80605" :knowledge-point/_questions [{:db/id 17592186124653 :knowledge-point/id #uuid "045854fc-9cad-5005-a306-9550848e25df" :knowledge-point/title "Finding the Critical Points of a Function"}] :question/answer-fields [{:answer-field/choices [{:answer/id #uuid "2a2a4e53-1b67-5b4b-b1ff-24dbbe84d43d" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "(-1,2)" :db/id 17592186434952} {:answer/id #uuid "ac84a034-8408-51a1-b95f-a12af62e4ba1" :answer/type {:db/id 17592186045499 :db/ident :answer.type/text} :answer/value "$(1,2)$ and $(1,-2)$" :db/id 17592186434963} {:answer/id #uuid "af3044d7-995b-5b31-911a-1432e5fb9524" :answer/type {:db/id 17592186045499 :db/ident :answer.type/text} :answer/value "$(1,2)$ and $(-1,-2)$" :db/id 17592186434964} {:answer/id #uuid "ef89c4a6-451f-5b35-895b-c5f4bf15a46a" :answer/type {:db/id 17592186045499 :db/ident :answer.type/text} :answer/value "$(-1,2)$ and $(1,2)$" :db/id 17592186434973} {:answer/id #uuid "f0c1486d-d897-5524-a326-f95ed8d30db0" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "(1,-2)" :db/id 17592186434974}] :answer-field/correct {:answer/id #uuid "2a2a4e53-1b67-5b4b-b1ff-24dbbe84d43d" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "(-1,2)" :db/id 17592186434952} :answer-field/id #uuid "4639d8d2-4eac-541e-8594-82bea3d94f3f" :answer-field/key "selection" :answer-field/type {:db/id 17592186045493 :db/ident :answer-field.type/radio} :db/id 17592186434977}] :question/difficulty {:db/id 17592186045485 :db/ident :question.difficulty/easy} :question/problem "Determine the stationary points of $f(x,y)={x}^{2}+xy+2\operatorname{ln}⁡y.$" :question/worked-solution "The stationary points of a multivariable function $f$ are the points $a$ in the domain of $f$ such that ${f}^{′}(a)={0}^{T},$ where

$$
{f}^{′}(a)={\begin{bmatrix}\frac{∂f}{∂{x}_{1}} & \frac{∂f}{∂{x}_{2}} & ⋯ & \frac{∂f}{∂{x}_{n}}\end{bmatrix}|}_{x=a}.
$$

In this case, the domain of $f$ is $D=\{(x,y)\in {R}^{2}∣y>0\},$ and the first partial derivatives of $f$ are

$$
\begin{aligned}\frac{∂f}{∂x} & =2x+y \\ \frac{∂f}{∂y} & =x+\frac{2}{y}.\end{aligned}
$$



So, the first derivative of $f$ is

$$
{f}^{′}(x,y)=\begin{bmatrix}2x+y & x+\frac{2}{y}\end{bmatrix}.
$$

To find the stationary points, we need to find the points where ${f}^{′}(x,y)={0}^{T}.$
Setting ${f}^{′}(x,y)={0}^{T},$ we have the following system:

$$
\{\begin{aligned}2x+y=0 \\ x+\frac{2}{y}=0\end{aligned}
$$

Solving for $y$ in the first equation, we get

$$
2x+y=0\,⟹\,y=-2x.
$$

Then, substituting into the second equation, we obtain

$$
\begin{aligned}x+\frac{2}{-2x} & =0 \\ x-\frac{1}{x} & =0 \\ x & =\frac{1}{x} \\ x & =\pm 1.\end{aligned}
$$

Back-substituting these values into $y=-2x,$ we get

$$
\begin{aligned}x=-1 & \,⟹\,y=-2(-1)=2 \\ x=1 & \,⟹\,y=-2(1)=-2.\end{aligned}
$$

Therefore, our system has two solutions, $(-1,2)$ and $(1,-2).$ We reject the point $(1,-2)$ because it does not lie in the domain of $f(x,y).$

In conclusion, $f$ has one stationary point, $(-1,2).$"} {:db/id 17592186124654 :knowledge-point/canonical-example {:db/id 17592186124217 :question/id #uuid "7c9f4b9e-be60-5da1-a140-08a3f183ce0e" :question/math-academy-id "e-12585"} :knowledge-point/id #uuid "4ca319c5-9f62-51e3-b670-611fc8a8daaa" :knowledge-point/key-prerequisites [{:db/id 17592186048859} {:db/id 17592186049044}] :knowledge-point/questions [{:db/id 17592186125067 :question/id #uuid "8a07adee-cd5f-5906-86f1-fee57d6ba6a8" :question/math-academy-id "q-37378"} {:db/id 17592186125081 :question/id #uuid "c3ea19ab-9bf6-5660-afe0-39f6942a18e3" :question/math-academy-id "q-37588"} {:db/id 17592186235548 :question/id #uuid "639c389b-5b21-519e-ae38-215c82f19461" :question/math-academy-id "q-168868"} {:db/id 17592186240969 :question/id #uuid "bcc06ba1-1065-5981-a107-14dc46cea80e" :question/math-academy-id "q-104984"} {:db/id 17592186240970 :question/id #uuid "e273e9fd-fb16-5b0e-b15b-fcbb70918d78" :question/math-academy-id "q-104995"} {:db/id 17592186323917 :question/id #uuid "14dd51d6-4da8-56bc-8036-6e67390713d4" :question/math-academy-id "q-37449"} {:db/id 17592186351244 :question/id #uuid "5521ee3b-fffd-5558-98b1-b81f3a08c9ea" :question/math-academy-id "q-81164"} {:db/id 17592186364681 :question/id #uuid "a2adfa73-7e18-5d5d-8163-694e5efa8a14" :question/math-academy-id "q-104980"} {:db/id 17592186368784 :question/id #uuid "7ba712ba-8939-58aa-ab47-15caf19c7eaa" :question/math-academy-id "q-81165"} {:db/id 17592186368791 :question/id #uuid "8ce3eb01-5fdc-5cad-ba01-77459c09b714" :question/math-academy-id "q-81166"} {:db/id 17592186420504 :question/id #uuid "d1a7556c-36af-5f0b-b64c-a00089e6850e" :question/math-academy-id "q-37456"} {:db/id 17592186434983 :question/id #uuid "b007310c-a11f-531c-b695-1febe8ef0462" :question/math-academy-id "q-37589"}] :knowledge-point/title "Classifying a Critical Point Using the Second Partial Derivatives Test"} {:db/id 17592186124217 :question/id #uuid "7c9f4b9e-be60-5da1-a140-08a3f183ce0e" :question/math-academy-id "e-12585" :knowledge-point/_canonical-example [{:db/id 17592186124654 :knowledge-point/id #uuid "4ca319c5-9f62-51e3-b670-611fc8a8daaa" :knowledge-point/title "Classifying a Critical Point Using the Second Partial Derivatives Test"}] :question/problem "The function 
$f(x,y) 
%= 2x + 2y - x^2 + y^2 + 2$
has the first derivative
![](images/96/96b56307cdc944bde53e3c4e1eba075cc16bac736d834755d681afd001ba83ed.svg)
and has a stationary point at $(1,-1).$ If $H$ denotes the Hessian determinant of $f,$ which of the following statements are true?

I. $H(1,-1) > 0$

II. $\dfrac{\partial^2 f}{\partial x^2}(1,-1) <    0$

III. The point $(1,-1)$ is a saddle point of $f$" :question/worked-solution "The second partial derivative test states that if $\mathbf{a}\in\mathbb{R}^2$ is a stationary point of $f(x,y)$ with Hessian determinant $H(\mathbf a),$ we have the following:

- If $H(\mathbf{a}) > 0,$ then:

- if $\dfrac{\partial^2 f}{\partial x^2}(\mathbf{a}) <                0,$ then $f$ has a local maximum at $\mathbf{a}$

- if $\dfrac{\partial^2 f}{\partial x^2}(\mathbf{a}) >0,$ then $f$ has a local minimum at $\mathbf{a}$

- If $H(\mathbf{a}) <       0,$ then $f$ has a saddle point at $\mathbf{a}$

- If $H(\mathbf{a}) = 0,$ then the second partial derivatives test is inconclusive.

First, we notice that since ![](images/76/764640d69311bf314da0b3dd729f5ac23ada3f536d7a175bfef77435fefad348.svg) we must have

$$
\dfrac{\partial f}{\partial x} = 2-2x, 
\qquad 
\dfrac{\partial f}{\partial y} =2+2y.
$$

Now, we compute the second partial derivatives:

$$
\begin{aligned}\frac{{∂}^{2}f}{∂{x}^{2}} & =\frac{∂}{∂x}(2-2x)=-2 \\ \frac{{∂}^{2}f}{∂{y}^{2}} & =\frac{∂}{∂y}(2+2y)=2 \\ \frac{{∂}^{2}f}{∂x∂y} & =\frac{{∂}^{2}f}{∂y∂x}=\frac{∂}{∂x}(2+2y)=0\end{aligned}
$$

So, the second derivative is

$$
\begin{aligned}{f}^{″}(x,y) & =\begin{bmatrix}\frac{{∂}^{2}f}{∂{x}^{2}} & \frac{{∂}^{2}f}{∂x∂y} \\ \frac{{∂}^{2}f}{∂y∂x} & \frac{{∂}^{2}f}{∂{y}^{2}}\end{bmatrix}=\begin{bmatrix}-2 & 0 \\ 0 & 2\end{bmatrix}.\end{aligned}
$$

Evaluating the second derivative at $(1,-1),$ we obtain

$$
\begin{aligned}{f}^{″}(1,-1)=\begin{bmatrix}-2 & 0 \\ 0 & 2\end{bmatrix}.\end{aligned}
$$

With that in mind, let's examine our statements in turn.

- Statement I is false. Computing the determinant of $\boldsymbol f''(1,-1),$ we get

$$
H(1,-1) = \det(\boldsymbol f''(1,-1)) = -2 \cdot 2 - 0^2 = -4 < 0.
$$

- Statement II is true. Indeed, we have $\dfrac{\partial^2 f}{\partial x^2}(1,-1) = (\boldsymbol f''(1,-1))_{11} = -2 \lt 0.$

- Statement III is true. Indeed, since $H(1,-1) < 0,$ the point $(1,-1)$ is a saddle point by the second partial derivative test.

Therefore, the correct answer is "II and III only.""} {:db/id 17592186125067 :question/id #uuid "8a07adee-cd5f-5906-86f1-fee57d6ba6a8" :question/math-academy-id "q-37378" :knowledge-point/_questions [{:db/id 17592186124654 :knowledge-point/id #uuid "4ca319c5-9f62-51e3-b670-611fc8a8daaa" :knowledge-point/title "Classifying a Critical Point Using the Second Partial Derivatives Test"}] :question/answer-fields [{:answer-field/choices [{:answer/id #uuid "f4f584a9-6d95-5612-8744-d5fbfa708ecd" :answer/type {:db/id 17592186045499 :db/ident :answer.type/text} :answer/value "false" :db/id 17592186448602} {:answer/id #uuid "3b704d1a-d453-5ae9-b16e-9648b4cae61d" :answer/type {:db/id 17592186045499 :db/ident :answer.type/text} :answer/value "true" :db/id 17592186448603}] :answer-field/correct {:answer/id #uuid "3b704d1a-d453-5ae9-b16e-9648b4cae61d" :answer/type {:db/id 17592186045499 :db/ident :answer.type/text} :answer/value "true" :db/id 17592186448603} :answer-field/id #uuid "5e4d092d-ab68-55b8-a9dd-d09047e18457" :answer-field/key "I" :answer-field/type {:db/id 17592186408166 :db/ident :answer-field.type/checkbox} :db/id 17592186449341} {:answer-field/choices [{:answer/id #uuid "a3f477b4-0a76-545d-9534-9ee9e479b83e" :answer/type {:db/id 17592186045499 :db/ident :answer.type/text} :answer/value "false" :db/id 17592186448604} {:answer/id #uuid "56bbbe13-48ff-50c2-9e7d-e8f5328a7cab" :answer/type {:db/id 17592186045499 :db/ident :answer.type/text} :answer/value "true" :db/id 17592186448605}] :answer-field/correct {:answer/id #uuid "56bbbe13-48ff-50c2-9e7d-e8f5328a7cab" :answer/type {:db/id 17592186045499 :db/ident :answer.type/text} :answer/value "true" :db/id 17592186448605} :answer-field/id #uuid "891512e6-efc1-5012-886f-462562b19dd2" :answer-field/key "II" :answer-field/type {:db/id 17592186408166 :db/ident :answer-field.type/checkbox} :db/id 17592186449342} {:answer-field/choices [{:answer/id #uuid "ba6c5ce0-1e8c-5b62-a69a-0ab64de4355b" :answer/type {:db/id 17592186045499 :db/ident :answer.type/text} :answer/value "false" :db/id 17592186448606} {:answer/id #uuid "d4ea928d-6f64-5b3b-b346-42aee05449b7" :answer/type {:db/id 17592186045499 :db/ident :answer.type/text} :answer/value "true" :db/id 17592186448607}] :answer-field/correct {:answer/id #uuid "ba6c5ce0-1e8c-5b62-a69a-0ab64de4355b" :answer/type {:db/id 17592186045499 :db/ident :answer.type/text} :answer/value "false" :db/id 17592186448606} :answer-field/id #uuid "06c4e907-d6c9-5f4a-bca0-10ea7c035feb" :answer-field/key "III" :answer-field/type {:db/id 17592186408166 :db/ident :answer-field.type/checkbox} :db/id 17592186449343}] :question/difficulty {:db/id 17592186045485 :db/ident :question.difficulty/easy} :question/problem "The function 
$f(x,y)$
has the second derivative

$$
{f}^{″}(x,y)=\begin{bmatrix}\frac{2(1+\operatorname{ln}⁡x)}{x} & 2y \\ 2y & 2x\end{bmatrix}
$$

and has a stationary point at $(1,0).$ If $H$ denotes the Hessian determinant of $f,$ which of the following statements are true?

Select all that apply.

- **I.** $H(1,0)>0$

- **II.** $\frac{{∂}^{2}f}{∂{x}^{2}}(1,0)>0$

- **III.** The point $(1,0)$ is a local maximum of $f$" :question/worked-solution "The second partial derivative test states that if $a\in {R}^{2}$ is a stationary point of $f(x,y)$ with Hessian determinant $H(a),$ we have the following:

- If $H(a)>0,$ then:

- if $\frac{{∂}^{2}f}{∂{x}^{2}}(a)<0,$ then $f$ has a local maximum at $a$

- if $\frac{{∂}^{2}f}{∂{x}^{2}}(a)>0,$ then $f$ has a local minimum at $a$

- If $H(a)<0,$ then $f$ has a saddle point at $a$

- If $H(a)=0,$ then the second partial derivatives test is inconclusive.

Evaluating the second derivative at $(1,0),$ we obtain

$$
\begin{aligned}{f}^{″}(1,0)=\begin{bmatrix}2 & 0 \\ 0 & 2\end{bmatrix}.\end{aligned}
$$

Now, let's examine our statements in turn.

- Statement I is true. Indeed, computing the determinant of ${f}^{″}(1,0),$ we get

$$
H(1,0)=det({f}^{″}(1,0))=2\cdot 2-{0}^{2}=4>0.
$$

- Statement II is true. Indeed, we have $\frac{{∂}^{2}f}{∂{x}^{2}}(1,0)=({f}^{″}(1,0))_{11}=2.$

- Statement III is false. Since $H(1,0)>0$ and $\frac{{∂}^{2}f}{∂{x}^{2}}(1,0)>0,$ the point $(1,0)$ is a local minimum by the second partial derivative test.

Therefore, the correct answer is, "I and II only.""} {:db/id 17592186125081 :question/id #uuid "c3ea19ab-9bf6-5660-afe0-39f6942a18e3" :question/math-academy-id "q-37588"} {:db/id 17592186235548 :question/id #uuid "639c389b-5b21-519e-ae38-215c82f19461" :question/math-academy-id "q-168868"} {:db/id 17592186240969 :question/id #uuid "bcc06ba1-1065-5981-a107-14dc46cea80e" :question/math-academy-id "q-104984" :knowledge-point/_questions [{:db/id 17592186124654 :knowledge-point/id #uuid "4ca319c5-9f62-51e3-b670-611fc8a8daaa" :knowledge-point/title "Classifying a Critical Point Using the Second Partial Derivatives Test"}] :question/answer-fields [{:answer-field/choices [{:answer/id #uuid "61346844-f5db-5d81-988d-5f22f99364e2" :answer/type {:db/id 17592186045499 :db/ident :answer.type/text} :answer/value "false" :db/id 17592186447690} {:answer/id #uuid "e325de96-c1e7-580b-b09d-da93b3fe3b32" :answer/type {:db/id 17592186045499 :db/ident :answer.type/text} :answer/value "true" :db/id 17592186447691}] :answer-field/correct {:answer/id #uuid "e325de96-c1e7-580b-b09d-da93b3fe3b32" :answer/type {:db/id 17592186045499 :db/ident :answer.type/text} :answer/value "true" :db/id 17592186447691} :answer-field/id #uuid "59cd2a41-7643-579c-a7be-c9328567102c" :answer-field/key "I" :answer-field/type {:db/id 17592186408166 :db/ident :answer-field.type/checkbox} :db/id 17592186448885} {:answer-field/choices [{:answer/id #uuid "65db9d78-e369-5af7-bf80-9aaea2cb0ae9" :answer/type {:db/id 17592186045499 :db/ident :answer.type/text} :answer/value "false" :db/id 17592186447692} {:answer/id #uuid "6608fb9a-406b-57eb-94b3-59aa661b60b8" :answer/type {:db/id 17592186045499 :db/ident :answer.type/text} :answer/value "true" :db/id 17592186447693}] :answer-field/correct {:answer/id #uuid "65db9d78-e369-5af7-bf80-9aaea2cb0ae9" :answer/type {:db/id 17592186045499 :db/ident :answer.type/text} :answer/value "false" :db/id 17592186447692} :answer-field/id #uuid "b0e6461c-403e-5a30-8b5c-3a1d65889782" :answer-field/key "II" :answer-field/type {:db/id 17592186408166 :db/ident :answer-field.type/checkbox} :db/id 17592186448886} {:answer-field/choices [{:answer/id #uuid "b9a29471-bdb1-5c51-8ffd-2502d26abe0f" :answer/type {:db/id 17592186045499 :db/ident :answer.type/text} :answer/value "false" :db/id 17592186447694} {:answer/id #uuid "5344e453-2eb8-5606-91f5-05f0b3a8e966" :answer/type {:db/id 17592186045499 :db/ident :answer.type/text} :answer/value "true" :db/id 17592186447695}] :answer-field/correct {:answer/id #uuid "5344e453-2eb8-5606-91f5-05f0b3a8e966" :answer/type {:db/id 17592186045499 :db/ident :answer.type/text} :answer/value "true" :db/id 17592186447695} :answer-field/id #uuid "d18799fe-c555-58ca-86dc-b96e74bdbd5a" :answer-field/key "III" :answer-field/type {:db/id 17592186408166 :db/ident :answer-field.type/checkbox} :db/id 17592186448887}] :question/difficulty {:db/id 17592186045485 :db/ident :question.difficulty/easy} :question/problem "The function 
$f(x,y)$ 
has the second derivative

$$
{f}^{″}(x,y)=\begin{bmatrix}{e}^{-({x}^{2}+{y}^{2})}(2{x}^{2}-1) & 2xy{e}^{-({x}^{2}+{y}^{2})} \\ 2xy{e}^{-({x}^{2}+{y}^{2})} & {e}^{-({x}^{2}+{y}^{2})}(2{y}^{2}-1)\end{bmatrix}
$$

and has a stationary point at $(0,0).$ If $H$ denotes the Hessian determinant of $f,$ which of the following statements are true?

Select all that apply.

- **I.** $H(0,0)>0$
- **II.** $\frac{{∂}^{2}f}{∂{x}^{2}}(0,0)>0$
- **III.** The point $(0,0)$ is a local maximum of $f$" :question/worked-solution "The second partial derivative test states that if $a\in {R}^{2}$ is a stationary point of $f(x,y)$ with Hessian determinant $H(a),$ we have the following:

- If $H(a)>0,$ then:

- if $\frac{{∂}^{2}f}{∂{x}^{2}}(a)<0,$ then $f$ has a local maximum at $a$

- if $\frac{{∂}^{2}f}{∂{x}^{2}}(a)>0,$ then $f$ has a local minimum at $a$

- If $H(a)<0,$ then $f$ has a saddle point at $a$

- If $H(a)=0,$ then the second partial derivatives test is inconclusive.

Evaluating the second derivative at $(0,0),$ we obtain

$$
\begin{aligned}{f}^{″}(0,0)=\begin{bmatrix}-1 & 0 \\ 0 & -1\end{bmatrix}.\end{aligned}
$$

Now, let's examine our statements in turn.

- Statement I is true. Indeed, computing the determinant of ${f}^{″}(0,0),$ we get

$$
H(0,0)=det({f}^{″}(0,0))=(-1)^{2}-{0}^{2}=1>0.
$$

- Statement II is false. We have $\frac{{∂}^{2}f}{∂{x}^{2}}(0,0)=({f}^{″}(0,0))_{11}=-1<0.$

- Statement III is true. Indeed, since $H(0,0)>0$ and $\frac{{∂}^{2}f}{∂{x}^{2}}(0,0)<0,$ the point $(0,0)$ is a local maximum by the second partial derivative test.

Therefore, the correct answer is "I and III only.""} {:db/id 17592186240970 :question/id #uuid "e273e9fd-fb16-5b0e-b15b-fcbb70918d78" :question/math-academy-id "q-104995"} {:db/id 17592186323917 :question/id #uuid "14dd51d6-4da8-56bc-8036-6e67390713d4" :question/math-academy-id "q-37449" :knowledge-point/_questions [{:db/id 17592186124654 :knowledge-point/id #uuid "4ca319c5-9f62-51e3-b670-611fc8a8daaa" :knowledge-point/title "Classifying a Critical Point Using the Second Partial Derivatives Test"}] :question/answer-fields [{:answer-field/choices [{:answer/id #uuid "76120093-e343-5052-a462-9eeed4935b72" :answer/type {:db/id 17592186045499 :db/ident :answer.type/text} :answer/value "false" :db/id 17592186450594} {:answer/id #uuid "555c0670-0865-5a00-b027-f58a0b26c69f" :answer/type {:db/id 17592186045499 :db/ident :answer.type/text} :answer/value "true" :db/id 17592186450595}] :answer-field/correct {:answer/id #uuid "555c0670-0865-5a00-b027-f58a0b26c69f" :answer/type {:db/id 17592186045499 :db/ident :answer.type/text} :answer/value "true" :db/id 17592186450595} :answer-field/id #uuid "3298d537-d11e-5eb5-b471-be1eb348f6fe" :answer-field/key "I" :answer-field/type {:db/id 17592186408166 :db/ident :answer-field.type/checkbox} :db/id 17592186451251} {:answer-field/choices [{:answer/id #uuid "1e466c1b-7f85-5787-9f33-f387b0440aa5" :answer/type {:db/id 17592186045499 :db/ident :answer.type/text} :answer/value "false" :db/id 17592186450596} {:answer/id #uuid "3a2b7b99-7dac-506f-8f5e-60849b213bf8" :answer/type {:db/id 17592186045499 :db/ident :answer.type/text} :answer/value "true" :db/id 17592186450597}] :answer-field/correct {:answer/id #uuid "1e466c1b-7f85-5787-9f33-f387b0440aa5" :answer/type {:db/id 17592186045499 :db/ident :answer.type/text} :answer/value "false" :db/id 17592186450596} :answer-field/id #uuid "1c78cee0-1b49-5dcb-820f-d25ea871fcfa" :answer-field/key "II" :answer-field/type {:db/id 17592186408166 :db/ident :answer-field.type/checkbox} :db/id 17592186451252} {:answer-field/choices [{:answer/id #uuid "5d90c823-2374-59b3-b675-22903d76217f" :answer/type {:db/id 17592186045499 :db/ident :answer.type/text} :answer/value "false" :db/id 17592186450598} {:answer/id #uuid "566b5d8d-7821-54bd-ac4b-b928d840baa2" :answer/type {:db/id 17592186045499 :db/ident :answer.type/text} :answer/value "true" :db/id 17592186450599}] :answer-field/correct {:answer/id #uuid "5d90c823-2374-59b3-b675-22903d76217f" :answer/type {:db/id 17592186045499 :db/ident :answer.type/text} :answer/value "false" :db/id 17592186450598} :answer-field/id #uuid "c44d6730-238d-5968-83bf-bfd50fc8649d" :answer-field/key "III" :answer-field/type {:db/id 17592186408166 :db/ident :answer-field.type/checkbox} :db/id 17592186451253}] :question/difficulty {:db/id 17592186045487 :db/ident :question.difficulty/moderate} :question/problem "The function   $f(x,y)$
has the first derivative

$$
{f}^{′}(x,y)=\begin{bmatrix}-{x}^{3}+2{x}^{2}+4y & 4x-2y\end{bmatrix}
$$

and has a stationary point at $(4,8).$ If $H$ denotes the Hessian determinant of $f,$ which of the following statements are true?

Select all that apply.

- **I.** $H(4,8)>0$
- **II.** $\frac{{∂}^{2}f}{∂{x}^{2}}(4,8)>0$
- **III.** The point $(4,8)$ is a saddle point of $f$" :question/worked-solution "The second partial derivative test states that if $a\in {R}^{2}$ is a stationary point of $f(x,y)$ with Hessian determinant $H(a),$ we have the following:

- If $H(a)>0,$ then:

- if $\frac{{∂}^{2}f}{∂{x}^{2}}(a)<0,$ then $f$ has a local maximum at $a$

- if $\frac{{∂}^{2}f}{∂{x}^{2}}(a)>0,$ then $f$ has a local minimum at $a$

- If $H(a)<0,$ then $f$ has a saddle point at $a$

- If $H(a)=0,$ then the second partial derivatives test is inconclusive.

First, we notice that since ${f}^{′}(x,y)=\begin{bmatrix}-{x}^{3}+2{x}^{2}+4y & 4x-2y\end{bmatrix},$ we must have 

$$
\frac{∂f}{∂x}=-{x}^{3}+2{x}^{2}+4y,\,\frac{∂f}{∂y}=4x-2y.
$$

Now, we compute the second partial derivatives:

$$
\begin{aligned}\frac{{∂}^{2}f}{∂{x}^{2}} & =\frac{∂}{∂x}(-{x}^{3}+2{x}^{2}+4y)=-3{x}^{2}+4x \\ \frac{{∂}^{2}f}{∂{y}^{2}} & =\frac{∂}{∂y}(4x-2y)=-2 \\ \frac{{∂}^{2}f}{∂x∂y} & =\frac{{∂}^{2}f}{∂y∂x}=\frac{∂}{∂x}(4x-2y)=4\end{aligned}
$$

So, the second derivative is

$$
\begin{aligned}{f}^{″}(x,y) & =\begin{bmatrix}\frac{{∂}^{2}f}{∂{x}^{2}} & \frac{{∂}^{2}f}{∂x∂y} \\ \frac{{∂}^{2}f}{∂y∂x} & \frac{{∂}^{2}f}{∂x∂y}\end{bmatrix}=\begin{bmatrix}-3{x}^{2}+4x & 4 \\ 4 & -2\end{bmatrix}.\end{aligned}
$$

Evaluating the second derivative at $(4,8),$ we obtain

$$
\begin{aligned}{f}^{″}(4,8)=\begin{bmatrix}-32 & 4 \\ 4 & -2\end{bmatrix}.\end{aligned}
$$

With that in mind, let's examine our statements in turn.

- Statement I is true. Indeed, computing the determinant of ${f}^{″}(4,8),$ we get

$$
H(4,8)=det({f}^{″}(4,8))=(-32)\cdot (-2)-{4}^{2}=48>0.
$$

- Statement II is false. We have $\frac{{∂}^{2}f}{∂{x}^{2}}(4,8)=({f}^{″}(4,8))_{11}=-32<0.$

- Statement III is false. Since $H(4,8)>0$ and $\frac{{∂}^{2}f}{∂{x}^{2}}(4,8)<0,$ the point $(4,8)$ is a local maximum by the second partial derivative test.

Therefore, the correct answer is "I only.""} {:db/id 17592186351244 :question/id #uuid "5521ee3b-fffd-5558-98b1-b81f3a08c9ea" :question/math-academy-id "q-81164"} {:db/id 17592186364681 :question/id #uuid "a2adfa73-7e18-5d5d-8163-694e5efa8a14" :question/math-academy-id "q-104980" :knowledge-point/_questions [{:db/id 17592186124654 :knowledge-point/id #uuid "4ca319c5-9f62-51e3-b670-611fc8a8daaa" :knowledge-point/title "Classifying a Critical Point Using the Second Partial Derivatives Test"}] :question/answer-fields [{:answer-field/choices [{:answer/id #uuid "62cbcaa0-0a4b-5073-ad88-c02a4ba1a019" :answer/type {:db/id 17592186045499 :db/ident :answer.type/text} :answer/value "false" :db/id 17592186451299} {:answer/id #uuid "375e98ca-c238-53ff-beba-897b64cc63a8" :answer/type {:db/id 17592186045499 :db/ident :answer.type/text} :answer/value "true" :db/id 17592186451300}] :answer-field/correct {:answer/id #uuid "62cbcaa0-0a4b-5073-ad88-c02a4ba1a019" :answer/type {:db/id 17592186045499 :db/ident :answer.type/text} :answer/value "false" :db/id 17592186451299} :answer-field/id #uuid "652213cb-11aa-5dea-a4bc-3b9c8b1c355c" :answer-field/key "I" :answer-field/type {:db/id 17592186408166 :db/ident :answer-field.type/checkbox} :db/id 17592186452497} {:answer-field/choices [{:answer/id #uuid "7b0d48c5-2f2c-5055-908e-0dc95f5f7282" :answer/type {:db/id 17592186045499 :db/ident :answer.type/text} :answer/value "false" :db/id 17592186451301} {:answer/id #uuid "61b6f0c7-25e4-5be3-b321-0d0f90827d6a" :answer/type {:db/id 17592186045499 :db/ident :answer.type/text} :answer/value "true" :db/id 17592186451302}] :answer-field/correct {:answer/id #uuid "61b6f0c7-25e4-5be3-b321-0d0f90827d6a" :answer/type {:db/id 17592186045499 :db/ident :answer.type/text} :answer/value "true" :db/id 17592186451302} :answer-field/id #uuid "d71cb01d-fa4d-51c3-8af9-10186ba20c84" :answer-field/key "II" :answer-field/type {:db/id 17592186408166 :db/ident :answer-field.type/checkbox} :db/id 17592186452498} {:answer-field/choices [{:answer/id #uuid "1bd7d602-b04e-508c-8f43-638a3bb96a1c" :answer/type {:db/id 17592186045499 :db/ident :answer.type/text} :answer/value "false" :db/id 17592186451303} {:answer/id #uuid "cafd6976-b47f-5881-a12d-13755ea64993" :answer/type {:db/id 17592186045499 :db/ident :answer.type/text} :answer/value "true" :db/id 17592186451304}] :answer-field/correct {:answer/id #uuid "cafd6976-b47f-5881-a12d-13755ea64993" :answer/type {:db/id 17592186045499 :db/ident :answer.type/text} :answer/value "true" :db/id 17592186451304} :answer-field/id #uuid "1a57395c-fb2f-5e27-af13-56da5d453d17" :answer-field/key "III" :answer-field/type {:db/id 17592186408166 :db/ident :answer-field.type/checkbox} :db/id 17592186452499}] :question/difficulty {:db/id 17592186045485 :db/ident :question.difficulty/easy} :question/problem "The function $f(x,y)$ has Hessian matrix

$$
{∇}^{2}f(x,y)=\begin{bmatrix}{x}^{2}+2(y-3) & 2(x+1) \\ 2(x+1) & (y-3)^{2}\end{bmatrix}
$$

and has a stationary point at $(-1,3).$ If $H$ denotes the Hessian determinant of $f,$ which of the following statements are true?

Select all that apply.

- **I.** $H(-1,3)<0$
- **II.** $\frac{{∂}^{2}f}{∂{x}^{2}}(-1,3)>0$
- **III.** The second partial derivative test is inconclusive" :question/worked-solution "The second partial derivative test states that if $a\in {R}^{2}$ is a stationary point of $f(x,y)$ with Hessian determinant $H(a),$ then:

- If $H(a)>0,$ then:

- if $\frac{{∂}^{2}f}{∂{x}^{2}}(a)<0,$ then $f$ has a local maximum at $a$;

- if $\frac{{∂}^{2}f}{∂{x}^{2}}(a)>0,$ then $f$ has a local minimum at $a.$

- If $H(a)<0,$ then $f$ has a saddle point at $a.$

- If $H(a)=0,$ then the second partial derivative test is inconclusive.

Evaluating the Hessian at $(-1,3),$ we obtain

$$
{∇}^{2}f(-1,3)=\begin{bmatrix}(-1)^{2}+2(3-3) & 2(-1+1) \\ 2(-1+1) & (3-3)^{2}\end{bmatrix}=\begin{bmatrix}1 & 0 \\ 0 & 0\end{bmatrix}.
$$

Now, let's examine the statements.

- Statement I is false. The Hessian determinant is

$$
H(-1,3)=det({∇}^{2}f(-1,3))=1(0)-0(0)=0.
$$

- Statement II is true because

$$
\frac{{∂}^{2}f}{∂{x}^{2}}(-1,3)=1>0.
$$

- Statement III is true because $H(-1,3)=0,$ so the second partial derivative test is inconclusive.

Therefore, the correct answer is "II and III only.""} {:db/id 17592186368784 :question/id #uuid "7ba712ba-8939-58aa-ab47-15caf19c7eaa" :question/math-academy-id "q-81165"} {:db/id 17592186368791 :question/id #uuid "8ce3eb01-5fdc-5cad-ba01-77459c09b714" :question/math-academy-id "q-81166"} {:db/id 17592186420504 :question/id #uuid "d1a7556c-36af-5f0b-b64c-a00089e6850e" :question/math-academy-id "q-37456"} {:db/id 17592186434983 :question/id #uuid "b007310c-a11f-531c-b695-1febe8ef0462" :question/math-academy-id "q-37589" :knowledge-point/_questions [{:db/id 17592186124654 :knowledge-point/id #uuid "4ca319c5-9f62-51e3-b670-611fc8a8daaa" :knowledge-point/title "Classifying a Critical Point Using the Second Partial Derivatives Test"}] :question/answer-fields [{:answer-field/choices [{:answer/id #uuid "b99dcd31-0696-5ae3-a002-0700a699c3c6" :answer/type {:db/id 17592186045499 :db/ident :answer.type/text} :answer/value "false" :db/id 17592186453886} {:answer/id #uuid "b13cab50-ce9f-50ad-b0dc-b0f33b90172e" :answer/type {:db/id 17592186045499 :db/ident :answer.type/text} :answer/value "true" :db/id 17592186453887}] :answer-field/correct {:answer/id #uuid "b13cab50-ce9f-50ad-b0dc-b0f33b90172e" :answer/type {:db/id 17592186045499 :db/ident :answer.type/text} :answer/value "true" :db/id 17592186453887} :answer-field/id #uuid "aa4b6b9c-5d2a-594c-960e-1c4e75c64792" :answer-field/key "I" :answer-field/type {:db/id 17592186408166 :db/ident :answer-field.type/checkbox} :db/id 17592186454693} {:answer-field/choices [{:answer/id #uuid "6df70a2f-70bb-5fcc-ae8d-49c71465bbc0" :answer/type {:db/id 17592186045499 :db/ident :answer.type/text} :answer/value "false" :db/id 17592186453888} {:answer/id #uuid "eeb49d3c-662c-5e17-871f-5d0e954249ba" :answer/type {:db/id 17592186045499 :db/ident :answer.type/text} :answer/value "true" :db/id 17592186453889}] :answer-field/correct {:answer/id #uuid "eeb49d3c-662c-5e17-871f-5d0e954249ba" :answer/type {:db/id 17592186045499 :db/ident :answer.type/text} :answer/value "true" :db/id 17592186453889} :answer-field/id #uuid "abbc8d9a-f48f-5dd7-ab15-6b078f09b474" :answer-field/key "II" :answer-field/type {:db/id 17592186408166 :db/ident :answer-field.type/checkbox} :db/id 17592186454694} {:answer-field/choices [{:answer/id #uuid "25f80279-e5d1-50e6-9fc4-c16efd13157c" :answer/type {:db/id 17592186045499 :db/ident :answer.type/text} :answer/value "false" :db/id 17592186453890} {:answer/id #uuid "b82e04f0-14eb-531c-b7af-055ded9e9fa6" :answer/type {:db/id 17592186045499 :db/ident :answer.type/text} :answer/value "true" :db/id 17592186453891}] :answer-field/correct {:answer/id #uuid "25f80279-e5d1-50e6-9fc4-c16efd13157c" :answer/type {:db/id 17592186045499 :db/ident :answer.type/text} :answer/value "false" :db/id 17592186453890} :answer-field/id #uuid "fdec8465-2901-52b6-a16f-9134ee75d3b0" :answer-field/key "III" :answer-field/type {:db/id 17592186408166 :db/ident :answer-field.type/checkbox} :db/id 17592186454695}] :question/difficulty {:db/id 17592186045485 :db/ident :question.difficulty/easy} :question/problem "The function 
$f(x,y)$ 
has the second derivative

$$
{f}^{″}(x,y)=\begin{bmatrix}12{x}^{2}-4 & 0 \\ 0 & 2\end{bmatrix}
$$

and has a stationary point at $(-1,0).$ If $H$ denotes the Hessian determinant of $f,$ which of the following statements are true?

Select all that apply.

- **I.** $H(-1,0)>0$

- **II.** $\frac{{∂}^{2}f}{∂{x}^{2}}(-1,0)>0$

- **III.** The point $(-1,0)$ is a local maximum of $f$" :question/worked-solution "The second partial derivative test states that if $a\in {R}^{2}$ is a stationary point of $f(x,y)$ with Hessian determinant $H(a),$ we have the following:

- If $H(a)>0,$ then:

- if $\frac{{∂}^{2}f}{∂{x}^{2}}(a)<0,$ then $f$ has a local maximum at $a$

- if $\frac{{∂}^{2}f}{∂{x}^{2}}(a)>0,$ then $f$ has a local minimum at $a$

- If $H(a)<0,$ then $f$ has a saddle point at $a$

- If $H(a)=0,$ then the second partial derivatives test is inconclusive.

Evaluating the second derivative at $(-1,0),$ we obtain 

$$
\begin{aligned}{f}^{″}(-1,0)=\begin{bmatrix}8 & 0 \\ 0 & 2\end{bmatrix}.\end{aligned}
$$

Now, let's examine our statements in turn.

- Statement I is true. Indeed, computing the determinant of ${f}^{″}(-1,0),$ we get

$$
H(-1,0)=det({f}^{″}(-1,0))=8\cdot 2-{0}^{2}=16>0.
$$

- Statement II is true. Indeed, we have $\frac{{∂}^{2}f}{∂{x}^{2}}(-1,0)=({f}^{″}(-1,0))_{11}=8>0.$

- Statement III is false. Since $H(-1,0)>0$ and $\frac{{∂}^{2}f}{∂{x}^{2}}(-1,0)>0,$ the point $(-1,0)$ is a local minimum by the second partial derivative test.

Therefore, the correct answer is "I and II only.""} {:db/id 17592186124655 :knowledge-point/canonical-example {:db/id 17592186124218 :question/id #uuid "e5398577-d70c-56f9-9c89-4a9d4e8f1d45" :question/math-academy-id "e-12586"} :knowledge-point/id #uuid "61cadd46-5fae-51c6-8e5b-8114e48b12da" :knowledge-point/questions [{:db/id 17592186125083 :question/id #uuid "c1fd6c16-60ce-56fa-b03a-b1f876d9acf4" :question/math-academy-id "q-37590"} {:db/id 17592186125084 :question/id #uuid "e71f4d1b-7ab2-518d-aa98-4d69ed0f6542" :question/math-academy-id "q-37592"} {:db/id 17592186241041 :question/id #uuid "9136d3e6-f2a0-5b9c-a6a2-efe0a42ad6ee" :question/math-academy-id "q-105335"} {:db/id 17592186351207 :question/id #uuid "6d35a3af-0061-562b-9545-45ddd0993045" :question/math-academy-id "q-81043"} {:db/id 17592186351245 :question/id #uuid "ee951228-2bde-5532-9c92-cd8f867b2b2e" :question/math-academy-id "q-81167"} {:db/id 17592186364688 :question/id #uuid "265e39ea-f8c9-5146-9ac4-7988205838c0" :question/math-academy-id "q-105284"} {:db/id 17592186366372 :question/id #uuid "16f8ddbb-3563-5450-8b85-07ba89da4f50" :question/math-academy-id "q-81041"} {:db/id 17592186399468 :question/id #uuid "7f004a40-028a-581c-ab25-3ac8bd7f4fe7" :question/math-academy-id "q-105281"} {:db/id 17592186399475 :question/id #uuid "e1b5f6e8-a9c9-5be3-86f7-77f082bfcf04" :question/math-academy-id "q-105338"} {:db/id 17592186434981 :question/id #uuid "05076731-f2b5-5426-b032-1f0962af8ee1" :question/math-academy-id "q-105278"} {:db/id 17592186434982 :question/id #uuid "0a336a18-c506-59a2-baef-25499733a8d5" :question/math-academy-id "q-81179"}] :knowledge-point/title "Finding and Classifying All Critical Points Using the Second Partial Derivatives Test"} {:db/id 17592186124218 :question/id #uuid "e5398577-d70c-56f9-9c89-4a9d4e8f1d45" :question/math-academy-id "e-12586" :knowledge-point/_canonical-example [{:db/id 17592186124655 :knowledge-point/id #uuid "61cadd46-5fae-51c6-8e5b-8114e48b12da" :knowledge-point/titl