021} {:answer/id #uuid "7176ed6c-39a7-5cdd-9307-0416bd40591e" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "0.3015" :db/id 17592186444027} {:answer/id #uuid "f0da8eba-7a84-58c0-a725-444fe641d59d" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "0.3264" :db/id 17592186444035} {:answer-field/choices [{:answer/id #uuid "65f2abb0-f4a9-5c49-b1bf-402f28d52bc7" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "0.0047" :db/id 17592186421578} {:answer/id #uuid "6c55880a-7dc0-5d85-971e-c6e7ea95264d" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "0.0055" :db/id 17592186421579} {:answer/id #uuid "7158a375-0ebf-5d37-976b-e42ece269ac1" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "0.0060" :db/id 17592186421580} {:answer/id #uuid "a3ff9bc9-da2b-5dd6-ab09-e1939754ca30" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "0.0033" :db/id 17592186421590} {:answer/id #uuid "b31a223e-b919-56fb-b210-1641a36a0596" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "0.0062" :db/id 17592186421596}] :answer-field/correct {:answer/id #uuid "b31a223e-b919-56fb-b210-1641a36a0596" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "0.0062" :db/id 17592186421596} :answer-field/id #uuid "ecd948f6-0fc7-557e-95fe-81a08ab35f83" :answer-field/key "selection" :answer-field/type {:db/id 17592186045493 :db/ident :answer-field.type/radio} :db/id 17592186421621} {:answer/id #uuid "65f2abb0-f4a9-5c49-b1bf-402f28d52bc7" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "0.0047" :db/id 17592186421578} {:answer/id #uuid "6c55880a-7dc0-5d85-971e-c6e7ea95264d" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "0.0055" :db/id 17592186421579} {:answer/id #uuid "7158a375-0ebf-5d37-976b-e42ece269ac1" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "0.0060" :db/id 17592186421580} {:answer/id #uuid "a3ff9bc9-da2b-5dd6-ab09-e1939754ca30" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "0.0033" :db/id 17592186421590} {:answer/id #uuid "b31a223e-b919-56fb-b210-1641a36a0596" :answer/type {:db/id 17592186045498 :db/ident :answer.type/math} :answer/value "0.0062" :db/id 17592186421596} {:activity/expected-seconds 540.0 :activity/first-step {:db/id 17592186163072} :activity/id #uuid "939bf5d7-74f2-5e39-8966-774b0988be35" :activity/scope {:db/id 17592186049180 :topic/id #uuid "e15bf21d-dbff-5eda-89f0-4137a4ce7951" :topic/math-academy-id 3067} :activity/steps [{:db/id 17592186163072 :step/content {:db/id 17592186163327 :tutorial/content "Let $X_1, X_2, \ldots, X_{n}$ be a random sample of size $n$ drawn from a normal population $N(\mu,\sigma^2)$ with mean $\mu$ and variance $\sigma^2.$ In other words,   

$$
X_1, X_2, \ldots, X_{n} \sim N(\mu,\sigma^2).
$$

In this case, we can easily determine the sampling distribution of the sample mean

$$
\overline{X} = \dfrac{1}{n} \sum\limits_{i=1}^n X_i.
$$

Recall the following:

- The sum of $n$ independent and identically distributed normal random variables is normally distributed. Thus, 

$$
Y = \displaystyle \sum\limits_{i=1}^n X_i
$$

is normally distributed.

- A normally distributed random variable scaled by a constant factor is normally distributed. Thus, 

$$
\overline{X} = \dfrac1n\cdot Y
$$

is normally distributed.

Also, we previously saw that the expected value of the sample mean equals the population mean, i.e., 

$$
\textrm{E}[\overline{X}] = \mu,
$$

and the variance of the sample mean is

$$
\textrm{Var}[\overline{X}] = \dfrac{\sigma^2}{n}.
$$

Putting all of this together, we obtain that

$$
\overline{X} \sim N\left(\mu, \dfrac{\sigma^2}{n}\right),
$$

In other words, the sample mean $\overline{X}$ is normally distributed with mean $\mu$ and variance $\dfrac{\sigma^2}{n}.$" :tutorial/id #uuid "14d0c44e-7b46-50e5-800f-e73c03b66e46" :tutorial/math-academy-id 6277 :tutorial/title "Introduction"} :step/id #uuid "a485f6ff-48be-57c5-ba9e-77d399d6168c" :step/math-academy-id 38046 :step/next {:db/id 17592186163073}} {:db/id 17592186163073 :step/content {:db/id 17592186162109 :knowledge-point/canonical-example {:db/id 17592186161675 :question/id #uuid "cc2a7119-cb80-575b-9e90-d20ea283de5d" :question/math-academy-id "e-10085"} :knowledge-point/id #uuid "1af00587-e4c1-5199-828a-357709e69785" :knowledge-point/key-prerequisites [{:db/id 17592186048382} {:db/id 17592186049674} {:db/id 17592186050606}] :knowledge-point/questions [{:db/id 17592186162310} {:db/id 17592186162385} {:db/id 17592186421624} {:db/id 17592186421626} {:db/id 17592186421629} {:db/id 17592186421630} {:db/id 17592186421631} {:db/id 17592186498514}] :knowledge-point/title "Stating the Distribution of the Sample Mean"} :step/id #uuid "a66882b2-817d-57e1-87b6-b618cba85d65" :step/math-academy-id 38047 :step/next {:db/id 17592186163074}} {:db/id 17592186163074 :step/content {:db/id 17592186162110 :knowledge-point/canonical-example {:db/id 17592186161676 :question/id #uuid "82ae81dd-526e-50de-850c-f1623aae21fb" :question/math-academy-id "e-10086"} :knowledge-point/id #uuid "0643d82d-39a0-544e-b4b1-f178d14e4e03" :knowledge-point/questions [{:db/id 17592186162378} {:db/id 17592186162386} {:db/id 17592186421627} {:db/id 17592186421849} {:db/id 17592186421850} {:db/id 17592186421851} {:db/id 17592186444046} {:db/id 17592186444048} {:db/id 17592186444049} {:db/id 17592186498591}] :knowledge-point/title "Calculating a Probability Involving a Sample Mean"} :step/id #uuid "384b68eb-0905-5ee4-9ed9-92926dca6994" :step/math-academy-id 38048 :step/next {:db/id 17592186163075}} {:db/id 17592186163075 :step/content {:db/id 17592186162111 :knowledge-point/canonical-example {:db/id 17592186161677 :question/id #uuid "8cbddf16-bfab-539b-bce1-5ccb59dc4313" :question/math-academy-id "e-10087"} :knowledge-point/id #uuid "fc5b49c9-5fd8-574b-aed6-4cec9421d3d1" :knowledge-point/questions [{:db/id 17592186162384} {:db/id 17592186162387} {:db/id 17592186421622} {:db/id 17592186421623} {:db/id 17592186421625} {:db/id 17592186421628} {:db/id 17592186444045} {:db/id 17592186444047} {:db/id 17592186498499} {:db/id 17592186498578}] :knowledge-point/title "Calculating a Probability Involving a Sample Mean in Context"} :step/id #uuid "65571357-9862-53b7-a78a-da750210d350" :step/math-academy-id 38051}] :activity/title "Sample Means From Normal Populations" :activity/type {:db/id 17592186045463 :db/ident :activity.type/lesson} :db/id 17592186162197} {:db/id 17592186163072 :step/content {:db/id 17592186163327 :tutorial/content "Let $X_1, X_2, \ldots, X_{n}$ be a random sample of size $n$ drawn from a normal population $N(\mu,\sigma^2)$ with mean $\mu$ and variance $\sigma^2.$ In other words,   

$$
X_1, X_2, \ldots, X_{n} \sim N(\mu,\sigma^2).
$$

In this case, we can easily determine the sampling distribution of the sample mean

$$
\overline{X} = \dfrac{1}{n} \sum\limits_{i=1}^n X_i.
$$

Recall the following:

- The sum of $n$ independent and identically distributed normal random variables is normally distributed. Thus, 

$$
Y = \displaystyle \sum\limits_{i=1}^n X_i
$$

is normally distributed.

- A normally distributed random variable scaled by a constant factor is normally distributed. Thus, 

$$
\overline{X} = \dfrac1n\cdot Y
$$

is normally distributed.

Also, we previously saw that the expected value of the sample mean equals the population mean, i.e., 

$$
\textrm{E}[\overline{X}] = \mu,
$$

and the variance of the sample mean is

$$
\textrm{Var}[\overline{X}] = \dfrac{\sigma^2}{n}.
$$

Putting all of this together, we obtain that

$$
\overline{X} \sim N\left(\mu, \dfrac{\sigma^2}{n}\right),
$$

In other words, the sample mean $\overline{X}$ is normally distributed with mean $\mu$ and variance $\dfrac{\sigma^2}{n}.$" :tutorial/id #uuid "14d0c44e-7b46-50e5-800f-e73c03b66e46" :tutorial/math-academy-id 6277 :tutorial/title "Introduction"} :step/id #uuid "a485f6ff-48be-57c5-ba9e-77d399d6168c" :step/math-academy-id 38046 :step/next {:db/id 17592186163073}} {:db/id 17592186163327 :tutorial/content "Let $X_1, X_2, \ldots, X_{n}$ be a random sample of size $n$ drawn from a normal population $N(\mu,\sigma^2)$ with mean $\mu$ and variance $\sigma^2.$ In other words,   

