$$
f(-3)=-2(-3)+1=7.
$$"} :step/id #uuid "589a89f1-3670-5a97-9173-deba2449c324" :step/next {:db/id 17592186506635}} {:answer-field/choices [{:answer/id #uuid "a90ff20b-46bc-563c-8a6d-2698d67747fc" :answer/type {:db/id 17592186045498} :answer/value "7" :db/id 17592186316068}] :answer-field/correct {:db/id 17592186316068} :answer-field/id #uuid "49330cc6-9572-5a0d-b1f2-3e73f8b2ef51" :answer-field/key "field-1" :answer-field/type {:db/id 17592186045492} :db/id 17592186316717} {:answer/id #uuid "a90ff20b-46bc-563c-8a6d-2698d67747fc" :answer/type {:db/id 17592186045498} :answer/value "7" :db/id 17592186316068} {:db/id 17592186506635 :step/content {:db/id 17592186317397 :question/answer-fields [{:answer-field/choices [{:answer/id #uuid "a066781a-6e52-5220-93ef-23ff199bd9a5" :answer/type {:db/id 17592186045498} :answer/value "5" :db/id 17592186316022}] :answer-field/correct {:db/id 17592186316022} :answer-field/id #uuid "c5f46bb7-8b99-5788-8b85-2ae0679bb181" :answer-field/key "field-1" :answer-field/type {:db/id 17592186045492} :db/id 17592186317019}] :question/difficulty {:db/id 17592186045485} :question/id #uuid "cc552628-2cac-58c1-ac79-840e54e9a1ec" :question/math-academy-id "q-343390" :question/problem "$$
