f80e-5c14-bfff-c684c31322e1" 17592186045417] [17592186065149 1063 17592186065362 17592186045417] [17592186065150 1058 17592186065151 17592186045417] [17592186065150 1061 206315 17592186045417] [17592186065150 1062 #uuid "963172d5-8251-51b5-aca6-4ecca42d86ee" 17592186045417] [17592186065150 1063 17592186064267 17592186045417] [17592186065151 1058 17592186065152 17592186045417] [17592186065151 1061 206318 17592186045417] [17592186065151 1062 #uuid "1d064d4d-5d1a-58f9-b5c9-1a03c3fe5caf" 17592186045417] [17592186065151 1063 17592186064268 17592186045417] [17592186065152 1058 17592186065153 17592186045417] [17592186065152 1061 206321 17592186045417] [17592186065152 1062 #uuid "295e95a9-3a8e-541c-bdff-bd462fa18b86" 17592186045417] [17592186065152 1063 17592186064269 17592186045417] [17592186065153 1061 206324 17592186045417] [17592186065153 1062 #uuid "343ddc12-c579-5e1b-8c2d-a42ac8017653" 17592186045417] [17592186065153 1063 17592186064270 17592186045417] [17592186065158 1058 17592186065159 17592186045417] [17592186065158 1061 23042 17592186045417] [17592186065158 1062 #uuid "589482bf-a622-576c-8b59-1c5332c13087" 17592186045417] [17592186065158 1063 17592186064273 17592186045417] [17592186065159 1058 17592186064993 17592186045417] [17592186065159 1061 23043 17592186045417] [17592186065159 1062 #uuid "b952eadc-3fe2-5be0-8961-f9af3dc6fcd5" 17592186045417] [17592186065159 1063 17592186065374 17592186045417] [17592186065347 1064 "Let's consider the graph of the function $y=f(x)$ on the closed interval $[0,7]$ shown below.

![](images/39/39851b8fc5658ccfd92711eb9fe7a00a730300a3bf2e635911bdd51ea69de37a.png)

The **critical points** of $f(x)$ are the values of $x$ where $f'(x)=0$ or $f'(x)$ doesn't exist. Graphically, those are the values where the tangent to the graph is horizontal or where the tangent does not exist, respectively.

In the given graph, we can see that 

- at $x=2,$ the tangent to the graph is horizontal, so we have $f'(x)=0,$ while

- at $x=4,$ there is a sharp corner, so $f'(x)$ doesn't exist.

So, there are two critical points, and their $x$-coordinates are $x=2$ and $x=4.$ 

In particular, a critical point is called a **stationary point** if $f'(x)=0.$ So here, the points $x=2$ and $x=4$ are both critical points, but only the point at $x=2$ is a stationary point.

![](images/4e/4e91994fa85a068ef847cbd82dc176569fd15ab2487dfff6936280e9a1deb634.png)" 17592186045417] [17592186065347 1065 2660 17592186045417] [17592186065347 1066 #uuid "36584e6c-f116-5ad4-bb03-576b0f7e9c0e" 17592186045417] [17592186065347 1067 "Introduction" 17592186045417] [17592186065362 1064 "Consider a curve $y=f(x)$ between two points $x=a$ and $x=b$. The **average rate of change** of $y=f(x)$ on the interval $x\in[a,b]$ is computed as follows:

$$
\dfrac{\Delta y}{\Delta x} = \dfrac{\text{change in}y}{\text{change in}x} = \dfrac{f(b)-f(a)}{b-a}
$$

Geometrically, the average rate of change represents the slope of the **secant line** which passes through $(a,f(a))$ and $(b,f(b))$.

![](images/2d/2d27bcc73d1bcb8545c058c06553e3f4bc80d5426a98f5bb90e4d4c0aef71108.png)

**Note:** In general, a secant is a line that intersects a curve at two or more distinct points." 17592186045417] [17592186065362 1065 312 17592186045417] [17592186065362 1066 #uuid "4e32384d-35c4-578e-b254-9cf90914529e" 17592186045417] [17592186065362 1067 "Introduction" 17592186045417] [17592186065374 1064 "Some critical points are **local extrema**. There are two types of local extrema:

- A **local minimum** is the lowest point of a valley in a graph. Equivalently, $x=a$ is a local minimum if for $x$ values "close" to $x=a,$ we have $f(x) \geq f(a)$.

- A **local maximum** is the highest point of a peak in a graph. Equivalently, $x=a$ is a local maximum if for $x$ values "close" to $x=a,$ we have $f(x) \leq f(a)$.

![](images/d6/d6fbdf74b282bd5b8172fcc7927f84bbdfd050a717794f3b40c8e58b83d7b87e.png)

On the graph above, the critical point at $x=4$ is a local minimum since it is the lowest point of a valley. Likewise, the critical point at $x=6$ is a local maximum since it is the highest point of a peak. But the critical point at $x=2$ is not a local extremum since it is neither a peak nor a valley.

The **global extrema** of a function in an interval are given by the lowest or highest points of the function's graph in the whole interval.

- The lowest point is the **global minimum**, whereas

- the highest point is the **global maximum**.

